-- seed-recipes.sql — generated by scripts/migrate/01-recipes.mjs. Do not edit by hand.
-- 55 recipes, 55 images.
--
-- Idempotent: ids are derived from the slug, so re-running updates in place
-- rather than duplicating. status and published_at are deliberately NOT
-- refreshed, so a re-run can never republish a recipe the editor hid.
--
-- Images are NOT uploaded here. Each media_assets row points at the existing
-- /media/... URL, which keeps working exactly as it does today. Phase 5 moves
-- the bytes into Storage and rewrites public_path.

begin;

-- ── this file requires seed-media.sql to have run first ───────────────────
-- media_assets has exactly ONE owner: 02-media.mjs. It holds the full
-- inventory, the code-reference graph, the dimensions and the origin/locked
-- classification, and it is the only place that knows which five of her
-- recipe photos are also hardcoded in a marketing page and must stay locked.
-- This file used to write the same 30 rows with different values and neither
-- ON CONFLICT clause updated the columns the other one set, so whichever ran
-- last quietly won. Now it writes none of them, and refuses to run early.
do $$
begin
  if not exists (select 1 from public.media_assets where source = 'migrated') then
    raise exception 'run seed-media.sql before seed-recipes.sql'
      using hint = 'media_assets is seeded by scripts/migrate/02-media.mjs';
  end if;
end
$$;

-- ── recipes ────────────────────────────────────────────────────────────────
insert into public.recipes (id, slug, legacy_slug, title, description, date, category, tags, prep_time_text, prep_minutes, servings, image_id, image_path, image_alt, intro, ingredients, steps, tip, extra, headings, status, published_at)
values ('d7f1ffa9-400d-525a-8a57-840d7d7c4572', 'asian-glazed-salmon-bites', null, 'קוביות סלמון ברוטב אסיאתי', 'קוביות סלמון שנצרבות במחבת ומצופות ברוטב סויה, סילאן וג׳ינג׳ר. מוגשות עם אורז לבן וירוקים לארוחת צהריים מהירה ומשביעה.', '2026-05-24'::date, 'צהריים', array['קל ומהיר', 'עתיר חלבון']::text[], 'לא צוין', null, '2-3 מנות', '645a3aca-96e8-5f4d-8485-4dbf8588ab82', '/media/client/recipes/asian-glazed-salmon-bites.webp', 'קוביות סלמון בקערה לצד אורז לבן וברוקולי ירוק', 'קוביות סלמון במחבת ברוטב אסיאתי, מוגשות לצד אורז וירוקים. בשבילי זו ארוחת הצהריים המושלמת: מהירה, עשירה בחלבון, ועם רוטב מתוק מלוח שנצמד לכל קובייה.

הסוד הוא לא לבשל את הסלמון עד הסוף בהתחלה. ככה הוא נשאר עסיסי גם אחרי שהוא חוזר למחבת עם הרוטב.', '[{"kind":"item","text":"500 גרם סלמון ללא העור"},{"kind":"sublabel","text":"לרוטב:"},{"kind":"item","text":"1/4 כוס סויה"},{"kind":"item","text":"2 כפות סילאן"},{"kind":"item","text":"כפית שמן שומשום"},{"kind":"item","text":"מיץ לימון מחצי לימון טרי"},{"kind":"item","text":"2-3 כפות מים פושרים"},{"kind":"item","text":"2 שיני שום כתושות"},{"kind":"item","text":"כפית ג׳ינג׳ר טרי מגורד"},{"kind":"item","text":"צ׳ילי גרוס"},{"kind":"item","text":"כף שומשום"}]'::jsonb, '["חותכים את הסלמון לקוביות.","מחממים את המחבת ומרססים מעט שמן. מוסיפים את קוביות הסלמון ומקפיצים 2-3 דקות עד שהן נצרבות מכל הצדדים, הן לא צריכות להיות עשויות לגמרי.","מעבירים את קוביות הסלמון לקערה ומניחים בצד.","מערבבים את כל רכיבי הרוטב ושופכים אותו לאותה המחבת. מבשלים תוך כדי ערבוב על אש בינונית עד שהרוטב מבעבע ומצטמצם קלות.","מחזירים את קוביות הסלמון למחבת עם הרוטב ומערבבים עד שהרוטב עוטף ונצמד אליהן.","מפזרים מעל בצל ירוק, ואפשר עוד שומשום.","מומלץ להגיש על אורז לבן ויש לנו ארוחה מושלמת. בתיאבון!"]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-05-24T00:00:00Z'::timestamptz)
