insert into public.recipes (id, slug, legacy_slug, title, description, date, category, tags, prep_time_text, prep_minutes, servings, image_id, image_path, image_alt, intro, ingredients, steps, tip, extra, headings, status, published_at)
values ('f5ec7935-7cbb-551f-8a64-6f1793befca9', 'autumn-quinoa-pumpkin-salad', null, 'סלט קינואה סתווי עם דלעת צלויה', 'סלט קינואה סתווי עם דלעת ופטריות צלויות בתנור, שקדים וחמוציות ורוטב טחינה לימוני שעוטף הכול. מזין, משביע ומלא סיבים.', '2025-09-21'::date, 'סלטים', array['צמחוני', 'ללא גלוטן']::text[], 'לא צוין', null, null, 'd4251a79-4def-5d59-8c06-5f0055ca83bf', '/media/client/recipes/autumn-quinoa-pumpkin-salad.webp', 'צלחת סלט קינואה עם קוביות דלעת, פטריות ובצל סגול', 'אני לא יודעת אם לקרוא לזה סלט או ארוחה, אבל זה כל כך טעים, מזין ומשביע.

הדלעת והפטריות נצלות בתנור עד שהן מתרככות, ורוטב הטחינה הלימוני עוטף את כל הסלט. עשיר בסיבים תזונתיים ומתאים לתזונה הים תיכונית שאנחנו כל כך אוהבים.', '[{"kind":"item","text":"3/4 כוס קינואה מבושלת על פי הוראות היצרן"},{"kind":"item","text":"דלעת קלופה חתוכה לקוביות"},{"kind":"item","text":"קופסת פטריות"},{"kind":"item","text":"בצל סגול"},{"kind":"item","text":"שמן זית, מלח גס"},{"kind":"item","text":"חופן כוסברה"},{"kind":"item","text":"חופן פטרוזיליה"},{"kind":"item","text":"חופן שקדים פרוסים"},{"kind":"item","text":"חופן חמוציות"},{"kind":"sublabel","text":"לרוטב:"},{"kind":"item","text":"3 כפות טחינה גולמית"},{"kind":"item","text":"מיץ לימון מלימון שלם סחוט"},{"kind":"item","text":"כפית מלח, מעט פלפל שחור"},{"kind":"item","text":"2 שיני שום כתושות"},{"kind":"item","text":"כפית דבש או סילאן"},{"kind":"item","text":"כף מים פושרים"}]'::jsonb, '["מכינים את הקינואה על פי הוראות היצרן.","מחממים תנור ל180 מעלות. חותכים את הדלעת לקוביות, פורסים את הפטריות וחוצים את הבצל לרבעים. מניחים על נייר אפייה, מזלפים שמן זית ומלח גס ומכניסים לתנור ל20-30 דקות עד ריכוך הדלעת.","מוציאים מהתנור וממתינים מעט שהירקות יתקררו.","מרכיבים את הסלט בקערה עם כל הרכיבים, שופכים את הרוטב ומערבבים היטב."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2025-09-21T00:00:00Z'::timestamptz)
