values ('2205a5ae-f4f9-59ee-8a24-abf206519a5e', 'baked-bulgur-lentil-mujadara', null, 'מג׳דרת בורגול ועדשים בתנור', 'מג׳דרת בורגול ועדשים שנאפית בתבנית אחת בתנור, בסגנון שגר ושכח. מנה צמחית חמימה ומשביעה עם מעט כלים ומינימום עבודה.', '2026-05-17'::date, 'ערב', array['קל ומהיר', 'צמחוני', 'טבעוני']::text[], 'לא צוין', null, null, '0fd21446-5805-5a4a-8115-9b11396e2b68', '/media/client/recipes/baked-bulgur-lentil-mujadara.webp', 'מג׳דרה אפויה בתבנית זכוכית מפוזרת בפטרוזיליה קצוצה', 'מג׳דרת בורגול ועדשים בתנור, בסגנון שגר ושכח. הכל נכנס לתבנית אחת, בלי הרבה כלים, וזו אחת המנות הכי קלות שיש לי.

זו מנה חמימה ומשביעה שאני אוהבת להכין כשמגיעים אורחים, או כשרוצים סיר אחד פשוט שמחזיק כמה ארוחות.', '[{"kind":"item","text":"3 כפות שמן זית"},{"kind":"item","text":"1 בצל לבן פרוס לרצועות"},{"kind":"item","text":"כף סילאן"},{"kind":"item","text":"1.5 כוסות בורגול או אורז"},{"kind":"item","text":"1 כוס עדשים ירוקות שטופות"},{"kind":"item","text":"2 שיני שום כתושות"},{"kind":"item","text":"כפית מלח, פלפל שחור, שום גבישי, 1/4 כפית כמון"},{"kind":"item","text":"3 כוסות מים רותחים"}]'::jsonb, '["מחממים תנור ל 180 מעלות.","בתחתית התבנית שמים שמן זית, מניחים את פרוסות הבצל עם כפית סילאן ומערבבים.","מוסיפים את הבורגול, העדשים, השום, התבלינים והמים הרותחים. מערבבים היטב.","מזלפים מעל מעט סילאן, מכסים באלומיניום או במכסה מתאים ומכניסים לתנור ל 25-30 דקות. אפשר לפתוח ולערבב באמצע האפייה, ואם צריך להוסיף נוזלים.","ב 5 הדקות האחרונות לאפייה מורידים את הכיסוי ואופים ללא כיסוי להשחמה עליונה.","מוציאים מהתנור ובתיאבון!"]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-05-17T00:00:00Z'::timestamptz)
