values ('8cde22c9-e350-50c9-8cd7-1e763799a4df', 'baked-quinoa-patties', null, 'קציצות קינואה אפויות', 'קציצות קינואה אפויות בתנור עם גזר, קישוא ועשבי תיבול, דרך טעימה ומזינה לנצל שאריות קינואה מהמקרר ולהכין מנה קלה.', '2026-02-22'::date, 'ערב', array['צמחוני', 'קל ומהיר']::text[], 'לא צוין', null, null, '49da2789-7e5a-5c47-8aa4-b6286375103b', '/media/client/recipes/baked-quinoa-patties.webp', 'צלחת עם קציצות קינואה אפויות וקערת רוטב טחינה', 'קציצות קינואה אפויות, בריאות וטעימות, שנולדו משאריות הקינואה של מתכון קודם. אם יש לכם קינואה שנשארה במקרר, רגע לפני שאתם זורקים, תישארו איתי כאן.

מערבבים הכל בקערה אחת, מכדררים לקציצות ומכניסים לתנור. כמעט בלי עבודה, והן סוגרות לגמרי את הפינה לצד סלט או עם רוטב טחינה.', '[{"kind":"item","text":"1.5 כוסות קינואה מבושלת"},{"kind":"item","text":"1 גזר מגורד"},{"kind":"item","text":"קישוא מגורד"},{"kind":"item","text":"בצל לבן קצוץ דק"},{"kind":"item","text":"1-2 שיני שום כתושות (לא חובה אך מוסיף)"},{"kind":"item","text":"חופן עשבי תיבול קצוצים: כוסברה, פטרוזיליה"},{"kind":"item","text":"2 ביצים"},{"kind":"item","text":"3 כפות קמח"},{"kind":"item","text":"כפית שטוחה מלח, פלפל שחור, פפריקה, אבקת שום"},{"kind":"item","text":"תרסיס שמן זית"}]'::jsonb, '["מטגנים קלות את הבצל במעט שמן זית עד ריכוך קל (אפשר גם להוסיף אותו טרי לקציצות, אבל אני מעדיפה לטגן אותו קודם כדי שיספיק להתרכך טוב).","מחממים תנור ל 180 מעלות.","מערבבים את כל הרכיבים בקערה עד שמתקבלת תערובת אחידה.","מכדררים לקציצות ומניחים על תבנית אפייה משומנת קלות.","מרססים את הקציצות בשמן זית ומכניסים לתנור לאפייה של 25-30 דקות עד שהן משחימות ומזהיבות."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-02-22T00:00:00Z'::timestamptz)
