values ('d3f59ba0-1ca6-5445-885c-1294b18ac0a8', 'baked-tofu-schnitzel', 'baked-tofu-schnitzel', 'שניצל טופו אפוי בציפוי קראנצ''י', 'שניצל טופו אפוי בציפוי פירורים פריך, אחרי מרינדת סויה ולימון. מנה טבעונית עתירת חלבון לצהריים, בלי טיפת טיגון.', '2025-12-14'::date, 'צהריים', array['צמחוני', 'טבעוני', 'עתיר חלבון']::text[], 'לא צוין', null, null, '01267f93-5355-54f0-8280-a8f0ede9f2d9', '/media/client/recipes/baked-tofu-schnitzel.webp', 'צלחת שניצלי טופו לצד קוסקוס ירקות וקערית רוטב אדום', 'שניצל טופו אפוי בציפוי קראנצ''י, בלי טיגון בכלל. מנה מזינה, טעימה וזריזה לארוחת צהריים.

הסוד הוא במרינדת הסויה והלימון שהטופו סופג לפני הציפוי, ובנייר אפייה משומן היטב שנותן לשניצלים את הפריכות.', '[{"kind":"sublabel","text":"לשניצל הטופו:"},{"kind":"item","text":"300 גרם (חבילה) טופו"},{"kind":"sublabel","text":"למרינדה:"},{"kind":"item","text":"1/4 כוס רוטב סויה"},{"kind":"item","text":"מיץ לימון"},{"kind":"sublabel","text":"לבלילה הנוזלית:"},{"kind":"item","text":"1/2 כוס משקה סויה / צמחי אחר"},{"kind":"item","text":"4 כפות קורנפלור"},{"kind":"item","text":"1/2 כפית מלח, כפית פפריקה, שן שום"},{"kind":"sublabel","text":"לציפוי:"},{"kind":"item","text":"כוס פירורי לחם + כפית פפריקה + כפית אבקת שום + חצי כפית מלח"},{"kind":"item","text":"תרסיס שמן זית"}]'::jsonb, '["סוחטים היטב את הטופו ופורסים אותו לפרוסות מלבניות, לא דקות מדי.","מעבירים לקופסה ושופכים מעל הטופו את הסויה והלימון, מכסים ומכניסים למקרר ל 30 דקות לפחות, כדי שהטופו יספוג את הטעמים.","מחממים תנור ל 200 מעלות.","מכינים 2 קערות: אחת עם הבלילה הנוזלית ואחת עם הציפוי.","טובלים כל מלבן טופו בבלילה הנוזלית ומיד לאחר מכן בקערה עם הפירורים, ומצפים היטב.","מניחים את השניצלים על גבי נייר אפייה משומן במעט שמן זית, זה חשוב כדי שהם ייצאו קריספיים מספיק.","מתיזים שמן זית מעל השניצלים ומכניסים לאפייה של 20-25 דקות, עד שנהיים קריספיים ושחומים."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2025-12-14T00:00:00Z'::timestamptz)
