values ('1b1cd268-3163-5c21-89e2-85df1226fcdf', 'baked-tofu-vegetable-patties', null, 'קציצות טופו וירק אפויות', 'קציצות טופו וירק אפויות בתנור, עשירות בחלבון ומלאות בבטטה, גזר וקישוא. תוספת מזינה וזריזה שמתאימה לכל ארוחה.', '2026-07-26'::date, 'צהריים', array['צמחוני', 'עתיר חלבון']::text[], 'לא צוין', null, null, 'ebe79136-b1d6-5f09-899b-3128dd93b919', '/media/client/recipes/baked-tofu-vegetable-patties.webp', 'קציצות טופו וירק על מצע יוגורט עם פלפל חריף', 'קציצות טופו וירק אפויות וממכרות. הן מזינות, הן זריזות, הן טעימות, הן עשירות בחלבון והן התוספת הבאה שלכם לכל ארוחה.

הכל נטחן יחד במעבד מזון, נאפה בתנור בלי טיפת טיגון, ויוצא קריספי מבחוץ ורך מבפנים.', '[{"kind":"item","text":"1 בטטה"},{"kind":"item","text":"1-2 גזרים"},{"kind":"item","text":"1 בצל לבן"},{"kind":"item","text":"1 זוקיני או קישוא"},{"kind":"item","text":"חבילת טופו (300 גרם)"},{"kind":"item","text":"2 ביצים L"},{"kind":"item","text":"3-4 כפות קמח או שיבולת שועל"},{"kind":"item","text":"חופן כוסברה ופטרוזיליה"},{"kind":"item","text":"2 שיני שום כתושות"},{"kind":"item","text":"כפית שטוחה מלח, פלפל שחור, פפריקה"},{"kind":"item","text":"שמן זית"}]'::jsonb, '["מחממים תנור ל 180 מעלות.","חותכים את הירקות בצורה גסה וטוחנים יחד במעבד מזון, או מגרדים את הירקות בעזרת פומפייה.","סוחטים היטב את הנוזלים מהירקות.","מעבירים לקערה גדולה. מגרדים את הטופו או מפוררים אותו עם הידיים ומוסיפים לקערת הירקות.","מוסיפים את הביצים, הקמח, התבלינים ועשבי התיבול. מערבבים היטב לתערובת אחידה.","יוצרים קציצות בעזרת ידיים מעט רטובות ומניחים על תבנית לתנור. משמנים את הקציצות בשמן זית.","מכניסים לתנור ל 20-25 דקות, עד שהן מעט קריספיות ושחומות. תהנו."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-07-26T00:00:00Z'::timestamptz)
