values ('68cb6bf0-09f1-5022-83d1-026407b863ed', 'baked-tuna-patties', 'baked-tuna-patties', 'קציצות טונה אפויות בתנור', 'קציצות טונה אפויות בתנור עם ירקות מגורדים, כוסברה ושיבולת שועל. עשירות בחלבון, פשוטות להכנה ומשלימות כל ארוחה בלי טיפת טיגון.', '2026-04-26'::date, 'צהריים', array['עתיר חלבון', 'קל ומהיר']::text[], 'לא צוין', null, null, '33db5f2c-2fc7-56ac-8bf8-cf12dc3e3f94', '/media/client/recipes/baked-tuna-patties.webp', 'קציצות טונה עם טחינה לצד אורז וקישואים בצלחת', 'קציצות הטונה האלה הן מהדברים שאני הכי אוהבת להכין כשאין לי כוח לבשל. משביעות, מפוצצות בחלבון וקלילות להכנה, בדיוק כמו שאנחנו אוהבים.

אני אופה אותן בתנור בלי טיפת טיגון, והן יוצאות שחומות מבחוץ ורכות מבפנים. תוספת חלבונית ומהירה לכל ארוחה.', '[{"kind":"item","text":"2 חבילות טונה במים"},{"kind":"item","text":"2 ביצים"},{"kind":"item","text":"1 בצל לבן קצוץ"},{"kind":"item","text":"2 שיני שום"},{"kind":"item","text":"1 גזר או קישוא מגורד"},{"kind":"item","text":"צרור כוסברה קצוצה"},{"kind":"item","text":"3 כפות שיבולת שועל"},{"kind":"item","text":"1 כף טריאקי (אופציונלי)"},{"kind":"item","text":"מלח, פלפל"}]'::jsonb, '["מחממים תנור ל 190 מעלות.","מערבבים את כל הרכיבים בקערה עד לתערובת אחידה.","יוצרים קציצות ומניחים אותן על נייר אפייה.","מכניסים לתנור ל 15 עד 20 דקות עד שהן שחומות."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-04-26T00:00:00Z'::timestamptz)
