values ('31687c00-6872-5ac5-894e-cafb1f012ded', 'baked-vegetable-latkes', null, 'לביבות ירק אפויות', 'לביבות ירק אפויות בתנור מבטטה, גזר, קישוא ותפוח אדמה. יוצאות קריספיות ושחומות בלי טיפת טיגון, וטעימות לצד מטבל קר.', '2025-11-02'::date, 'ערב', array['צמחוני']::text[], 'לא צוין', null, null, '29a088a1-3420-538d-80c5-0d3d28f2e23d', '/media/client/recipes/baked-vegetable-latkes.webp', 'תבנית מלאה בלביבות ירק אפויות לצד קערית יוגורט בשמן זית', 'אלה הלביבות הכי טעימות שאכלתי, ולגמרי לא רק לחנוכה. אפשר גם לטגן אותן, אבל לדעתי הן ממש טעימות גם ככה, אם לא יותר.

טיפ חשוב: אחרי גירור הירקות מוסיפים להם בערך כף מלח ומתחילים לעסות אותם עם הידיים. זה השלב שמוציא את כל הנוזלים, ואחר כך סוחטים היטב. ככה הלביבות לא מתפרקות. בתיאבון.', '[{"kind":"item","text":"1 בטטה"},{"kind":"item","text":"1 תפוח אדמה קטן"},{"kind":"item","text":"2 גזרים"},{"kind":"item","text":"1-2 זוקיני או קישואים"},{"kind":"item","text":"1 בצל לבן"},{"kind":"item","text":"2 ביצים L"},{"kind":"item","text":"4 כפות קמח"},{"kind":"item","text":"חופן כוסברה או פטרוזיליה"},{"kind":"item","text":"כפית מלח"},{"kind":"item","text":"כפית פלפל שחור"},{"kind":"item","text":"מעט שום גבישי"},{"kind":"item","text":"שמן זית להברשת הלביבות ולשימון התבנית"}]'::jsonb, '["מחממים תנור ל180 מעלות.","קולפים את הירקות, מגררים אותם בעזרת מעבד מזון (הרבה יותר מהיר) או פומפייה ומעבירים לקערה גדולה.","מוסיפים לירקות כף מלח ומעסים בידיים, שלב חשוב שמוציא את הנוזלים.","סוחטים ביסודיות את הנוזלים מהירקות ומחזירים אותם לקערה הגדולה.","מוסיפים את הביצים, הקמח, הכוסברה, הבצל והתיבול ומערבבים היטב לתערובת אחידה.","בעזרת ידיים מעט רטובות יוצרים לביבות.","משמנים היטב תבנית לתנור עם נייר אפייה ומניחים מעל את הלביבות. זה שלב חשוב כדי שהלביבות יצאו קריספיות ושחומות ממש כמו בטיגון.","מברישים או מרססים בשמן זית מעל כל לביבה.","אופים בתנור בערך 20 דקות עד השחמה.","אוכלים לצד מטבל טעים."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2025-11-02T00:00:00Z'::timestamptz)
