values ('937a630a-551a-555d-8f85-c6aa674a79ad', 'banana-oat-cookies', null, 'עוגיות שיבולת שועל, בננה ושוקולד צ׳יפס', 'עוגיות רכות משיבולת שועל, בננות בשלות וחמאת בוטנים עם שוקולד צ׳יפס. קלות להכנה, מנחמות ומתאימות גם לארוחת בוקר מהירה.', '2026-03-29'::date, 'מתוקים', array['צמחוני', 'קל ומהיר']::text[], 'לא צוין', null, null, 'd5aa4e88-7820-5e96-8324-03d9c0b0c65b', '/media/client/recipes/banana-oat-cookies.webp', 'יד מחזיקה עוגיית שיבולת שועל עם שוקולד צ׳יפס', 'עוגיות שוקולד צ׳יפס משיבולת שועל, קלות להכנה, טעימות ומנחמות.

הבסיס שלהן הוא בננות בשלות וחמאת בוטנים, בלי קמח ובלי סוכר לבן, והן יוצאות רכות ונעימות גם ביום שאחרי.', '[{"kind":"item","text":"2 בננות בשלות"},{"kind":"item","text":"ביצה"},{"kind":"item","text":"2 כפות חמאת בוטנים טבעית"},{"kind":"item","text":"3 כפות מייפל טבעי, דבש או סילאן"},{"kind":"item","text":"תמצית וניל"},{"kind":"item","text":"כוס וחצי שיבולת שועל עבה (אפשר גם דקה או חצי חצי)"},{"kind":"item","text":"כפית אבקת אפייה"},{"kind":"item","text":"כפית קינמון"},{"kind":"item","text":"קורט מלח"},{"kind":"item","text":"חופן שוקולד צ׳יפס או שוקולד מריר קצוץ"}]'::jsonb, '["מחממים תנור ל 170 מעלות.","מועכים את הבננות הבשלות, מוסיפים את הביצה, חמאת הבוטנים, המייפל והווניל ומערבבים.","מוסיפים את שיבולת השועל, אבקת האפייה, הקינמון וקורט המלח ומערבבים לתערובת אחידה.","מוסיפים את השוקולד צ׳יפס ומאחדים.","יוצרים עוגיות בעזרת כף, עדיף כף גלידה, ומניחים על תבנית עם נייר אפייה.","מכניסים לאפייה ל 12 עד 15 דקות."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-03-29T00:00:00Z'::timestamptz)
