values ('bddc8be8-5606-558f-840a-3e0a263636e4', 'bean-noodle-tofu-stir-fry', null, 'מוקפץ אטריות שעועית וטופו', 'מוקפץ אטריות שעועית עם טופו צרוב, ירקות פריכים ורוטב סויה סילאן וג׳ינג׳ר, ארוחה צמחונית עשירה בחלבון במחבת אחת.', '2026-03-01'::date, 'ערב', array['צמחוני', 'טבעוני', 'עתיר חלבון', 'קל ומהיר']::text[], 'לא צוין', null, null, '9e6b0ca2-3bf7-563f-86d8-025de32309a2', '/media/client/recipes/bean-noodle-tofu-stir-fry.webp', 'מחבת עם קוביות טופו, בוטנים קצוצים ובצל ירוק', 'מוקפץ אטריות שעועית וטופו, צמחוני, מהיר ומלא בחלבון. זו המנה שאני מכינה כשאין לי הרבה זמן אבל בא לי משהו טעים ומשביע.

הטופו נצרב במחבת עד שהוא זהוב, הירקות נשארים פריכים, והרוטב עם הסילאן, הג׳ינג׳ר והלימון עוטף הכל. בסוף מפזרים בצל ירוק וכוסברה והמנה מקבלת רעננות.', '[{"kind":"item","text":"2 כפות שמן זית"},{"kind":"item","text":"300 גרם טופו אלטרנטיב בטעם טבעי"},{"kind":"item","text":"חצי חבילת אטריות שעועית"},{"kind":"item","text":"3 שיני שום קצוצות"},{"kind":"item","text":"1/2 פלפל צ׳ילי אדום חריף"},{"kind":"item","text":"2 גזרים חתוכים לג׳וליאנים או פרוסים דק"},{"kind":"item","text":"1/4 כרוב לבן פרוס דק"},{"kind":"item","text":"1/2 בצל סגול פרוס דק"},{"kind":"item","text":"חופן בצל ירוק חתוך"},{"kind":"item","text":"חופן כוסברה קצוצה"},{"kind":"item","text":"אופציונלי: בוטנים קצוצים"},{"kind":"sublabel","text":"לרוטב:"},{"kind":"item","text":"1/4 כוס רוטב סויה"},{"kind":"item","text":"2 כפות סילאן"},{"kind":"item","text":"כפית שמן שומשום"},{"kind":"item","text":"כפית ג׳ינג׳ר טרי"},{"kind":"item","text":"3 שיני שום כתושות"},{"kind":"item","text":"מיץ לימון מלימון שלם"},{"kind":"item","text":"צ׳ילי גרוס"}]'::jsonb, '["מבשלים את אטריות השעועית לפי הוראות ההכנה שעל האריזה.","מייבשים את הטופו בעזרת נייר סופג וחותכים לקוביות.","מחממים שמן זית במחבת ווק או במחבת רחבה וצורבים את הטופו 2-3 דקות.","מוסיפים את השום והצ׳ילי ומטגנים מעט, מוסיפים את שאר הירקות, מערבבים ומקפיצים יחד.","מוסיפים את אטריות השעועית ומעליהן את הרוטב.","מערבבים הכל היטב יחד ומקפיצים כמה דקות. מוסיפים את הבצל הירוק והכוסברה."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-03-01T00:00:00Z'::timestamptz)
