values ('26c87547-97ef-57bc-8dde-43e739084be6', 'braised-cabbage-tomato-sauce', null, 'כרוב מבושל ברוטב עגבניות', 'כרוב מבושל לאט ברוטב עגבניות עד שהוא מגיע למרקם רך כמו ריבה. תוספת מנחמת ודלת קלוריות שמצוינת להגשה לצד אורז לבן.', '2025-09-14'::date, 'ערב', array['צמחוני', 'טבעוני', 'ללא גלוטן', 'דל קלוריות']::text[], 'לא צוין', null, null, '082feb17-6479-5d6b-84fc-e6b232d45173', '/media/client/recipes/braised-cabbage-tomato-sauce.webp', 'מחבת כרוב מבושל ברוטב אדום על מפה משובצת צהובה', 'זה מתכון של סבתא שלי, שעבר לאמא שלי, שעבר אליי, ועכשיו אליכם.

תוספת טעימה, קלילה ומנחמת, עשירה בערכים תזונתיים, דלה בקלוריות ומוסיפה מלא נפח למנה.

הסוד כדי לקבל את המרקם הרך והריבתי הוא סבלנות. כשנותנים לכרוב את התנאים ואת הזמן שלו, הוא באמת יכול להפוך לגורמה.', '[{"kind":"item","text":"2 כפות שמן זית"},{"kind":"item","text":"1 בצל לבן"},{"kind":"item","text":"4-5 שיני שום פרוסות דק"},{"kind":"item","text":"1 כרוב שלם בינוני"},{"kind":"item","text":"קופסה קטנה של רכז עגבניות (100 גרם)"},{"kind":"item","text":"חצי פחית (250 גרם) רסק עגבניות או עגבניות חתוכות דק"},{"kind":"item","text":"כף סילאן"},{"kind":"item","text":"כפית שטוחה פפריקה מרוקאית חריפה"},{"kind":"item","text":"כפית שטוחה פפריקה מתוקה"},{"kind":"item","text":"כף שטוחה מלח"},{"kind":"item","text":"1.5 כוסות מים רותחים"}]'::jsonb, '["פורסים את הבצל לרצועות דקות, את השום לפרוסות ואת הכרוב גם לרצועות.","מטגנים את הבצל בשמן זית עד ריכוך, מוסיפים את השום ואת התבלינים, המלח והפפריקה, ומערבבים.","כשהבצל והשום מזהיבים מוסיפים את הכרוב, נותנים לו קצת להזיע ומוסיפים את הרסק ורכז העגבניות, המים, הסילאן והתבלינים.","מערבבים טוב, מכסים, מביאים לרתיחה ולאחר מכן מנמיכים לאש נמוכה.","נותנים לכרוב להתבשל על אש נמוכה כשעה לפחות. אפשר לפתוח, לערבב בין לבין ולטעום אם צריך עוד תיבול, אבל הסוד הוא בישול ארוך על אש נמוכה.","מומלץ להגיש על אורז לבן."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2025-09-14T00:00:00Z'::timestamptz)
