values ('6dddf5f2-2e41-5e90-8977-6a8a1e578bdb', 'bulgur-jar-salad', null, 'סלט בורגול בצנצנת', 'סלט בורגול בצנצנת שמתארגן בחמש דקות: רוטב בתחתית ומעליו ירקות, בולגרית, חומוס ובורגול. מנה מוכנה לקחת לעבודה.', '2025-09-07'::date, 'סלטים', array['קל ומהיר', 'צמחוני']::text[], '5 דקות', 5, null, 'ef0f9998-fc68-59c7-8ec9-6bd66a8db77b', '/media/client/recipes/bulgur-jar-salad.webp', 'צנצנת סלט בורגול בשכבות עם חומוס, מלפפון וגבינה', 'אחד הפטנטים היותר טובים שהיו לי כאן, ואני לא מבינה איך אני עושה את זה רק עכשיו.

5 דקות הכנה, שמים את הרוטב בתחתית, משחקים עם הירקות, החלבון והפחמימה, סוגרים את הצנצנת ולוקחים כמנה לעבודה או ללימודים. אתם חייבים לשמור את הפטנט הזה.', '[{"kind":"item","text":"צנצנת שניתן לקנות בסטוק"},{"kind":"sublabel","text":"לרוטב, בתחתית הצנצנת:"},{"kind":"item","text":"שמן זית"},{"kind":"item","text":"לימון"},{"kind":"item","text":"שן שום"},{"kind":"item","text":"מלח"},{"kind":"item","text":"פלפל שחור"},{"kind":"item","text":"כפית בלסמי מצומצם"},{"kind":"sublabel","text":"לשכבות, לפי הסדר:"},{"kind":"item","text":"כף גרעיני דלעת"},{"kind":"item","text":"כוסברה ובצל ירוק קצוצים"},{"kind":"item","text":"קוביות בולגרית 5%"},{"kind":"item","text":"חצי בצל סגול קצוץ"},{"kind":"item","text":"קוביות מלפפון"},{"kind":"item","text":"6-7 עגבניות שרי חתוכות"},{"kind":"item","text":"מיני פלפל או חצי גמבה"},{"kind":"item","text":"3-4 כפות גרגרי חומוס מבושלים"},{"kind":"item","text":"4 כפות בורגול"}]'::jsonb, '["שמים בתחתית הצנצנת את שמן הזית, הלימון, שן השום, המלח, הפלפל השחור וכפית בלסמי מצומצם.","מוסיפים לצנצנת לפי הסדר הבא: כף גרעיני דלעת, כוסברה ובצל ירוק קצוצים, קוביות בולגרית, חצי בצל סגול קצוץ, קוביות מלפפון, עגבניות השרי, מיני פלפל או חצי גמבה, גרגרי החומוס והבורגול.","סוגרים את הצנצנת ולוקחים לעבודה או ללימודים.","שופכים לצלחת ומערבבים לפני האכילה."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2025-09-07T00:00:00Z'::timestamptz)
