values ('8456a6d1-5216-564a-81ec-b14236c510db', 'cabbage-carrot-rice', null, 'אורז עם כרוב וגזר', 'אורז בסמטי שמתבשל בסיר אחד עם כרוב לבן, גזר, בצל ושום. תוספת טבעונית מלאה בנפח וטעימה שמשדרגת כל ארוחה.', '2026-07-12'::date, 'צהריים', array['טבעוני', 'צמחוני', 'ללא גלוטן']::text[], 'לא צוין', null, null, 'f9f6691c-c3e0-5584-88b7-7d20d7abe00d', '/media/client/recipes/cabbage-carrot-rice.webp', 'סיר ברזל מלא באורז עם כרוב וגזר', 'אורז עם כרוב וגזר, תוספת מלאה בנפח, טעימה וכיפית לכל ארוחה.

הכרוב והגזר מצטמצמים בסיר עם הבצל והשום, האורז סופג את כל הטעם, והכל מתבשל יחד בסיר אחד.', '[{"kind":"item","text":"2-3 כפות שמן זית"},{"kind":"item","text":"1 כוס אורז לבן בסמטי"},{"kind":"item","text":"1 בצל לבן חתוך לקוביות"},{"kind":"item","text":"2-3 שיני שום קצוצות"},{"kind":"item","text":"1-2 גזרים מגורדים"},{"kind":"item","text":"רבע כרוב לבן חתוך לרצועות"},{"kind":"item","text":"כפית מלח, פלפל שחור, מעט פפריקה"},{"kind":"item","text":"2 כוסות מים רותחים"}]'::jsonb, '["קוצצים את הבצל, השום, הכרוב והגזר.","מטגנים בסיר רחב את הבצל והשום בשמן זית. אחרי שהבצל נהיה מעט שקוף מוסיפים את הכרוב והגזר.","מטגנים יחד, מתבלים ומערבבים עד שהכרוב והגזר מצטמצמים ומתרככים מעט.","מוסיפים את האורז ומטגנים עוד דקה.","מוסיפים 2 כוסות מים רותחים, מערבבים, מביאים לרתיחה ומכסים את הסיר.","מבשלים על אש נמוכה 20 דקות, עד שהאורז מוכן. בתיאבון."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-07-12T00:00:00Z'::timestamptz)
