values ('5c649d7c-4bf7-558c-8c41-7dc9a291d347', 'caesar-salad-crispy-chickpeas', null, 'סלט קיסר עם קרוטוני חומוס', 'סלט קיסר בגרסה מאוזנת ומהירה: לבבות חסה, רוטב קיסר קליל וקרוטוני חומוס אפויים וקראנצ''יים במקום קרוטוני לחם.', '2025-08-31'::date, 'סלטים', array['צמחוני', 'ללא גלוטן']::text[], 'לא צוין', null, null, 'e15b6a5a-85c6-5f53-841a-bea46c7af6fa', '/media/client/recipes/caesar-salad-crispy-chickpeas.webp', 'קערת סלט קיסר עם חומוס אפוי ופרמזן מגורר', 'סלט קיסר בגרסה המהירה והמאוזנת, עם קרוטוני חומוס קראנצ''יים במקום קרוטוני לחם.

זה סלט של חמש דקות עבודה שמתאים גם להריונות וגם למי שקצת שומר על הגזרה, או למי שמארח ורוצה סלט מיוחד ומהיר ברגע האחרון.', '[{"kind":"item","text":"2 לבבות קיסר"},{"kind":"item","text":"1-2 כפות פרמזן מגורר"},{"kind":"sublabel","text":"לקרוטוני חומוס:"},{"kind":"item","text":"1 קופסה גרגרי חומוס בשימורים"},{"kind":"item","text":"כף שמן זית"},{"kind":"item","text":"כפית שטוחה מלח"},{"kind":"item","text":"כפית פפריקה"},{"kind":"item","text":"כפית שום גבישי"},{"kind":"sublabel","text":"לרוטב קיסר:"},{"kind":"item","text":"2 כפות מיונז לייט"},{"kind":"item","text":"כף שמן זית"},{"kind":"item","text":"מיץ לימון מחצי לימון טרי"},{"kind":"item","text":"2 שיני שום כתוש"},{"kind":"item","text":"כפית חרדל דיז''ון"},{"kind":"item","text":"כפית דבש"},{"kind":"item","text":"חצי כפית מלח, חצי כפית פלפל שחור"},{"kind":"item","text":"כף מים פושרים"}]'::jsonb, '["מחממים תנור ל190 מעלות.","מניחים בקערה את גרגרי החומוס עם שמן הזית והתבלינים ומערבבים.","מעבירים לתבנית עם נייר אפייה ומכניסים לתנור ל20-25 דקות.","בקערה מערבבים היטב את כל רכיבי הרוטב.","שוטפים את החסות ומסדרים בקערה מתאימה. שופכים את הרוטב ומערבבים.","מוסיפים את גרגרי החומוס ומגישים."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2025-08-31T00:00:00Z'::timestamptz)
