values ('3972b679-86fe-55e9-8c07-5c499c67f508', 'cauliflower-asian-tahini', null, 'כרובית ברוטב טחינה אסייתי', 'פרחי כרובית שנשלקים ונאפים ומוגשים ברוטב טחינה אסייתי עם סויה, ג׳ינג׳ר ומייפל. מנה מרשימה לשולחן החג שקל מאוד להכין.', '2026-04-12'::date, 'ערב', array['צמחוני', 'טבעוני']::text[], 'לא צוין', null, null, '757f86a1-2ba9-5644-8074-6ddd94ecbdc8', '/media/client/recipes/cauliflower-asian-tahini.webp', 'כרובית ברוטב טחינה בצלחת הגשה מוארכת עם שומשום וכוסברה', 'זה מתכון שהעליתי לראשונה לפני שלוש שנים, ועד היום אני מקבלת עליו ים מחמאות. הכרובית הכי טעימה שתכינו.

מנה קלה ומרשימה שהולכת לקבל המון מחמאות בשולחן החג, והסוד שלה הוא הרוטב האגדי של טחינה, סויה, ג׳ינג׳ר ומייפל.', '[{"kind":"item","text":"כרובית שלמה טרייה"},{"kind":"item","text":"תרסיס שמן זית"},{"kind":"sublabel","text":"לרוטב:"},{"kind":"item","text":"4 כפות טחינה גולמית"},{"kind":"item","text":"4 כפות סויה"},{"kind":"item","text":"2 שיני שום כתושות"},{"kind":"item","text":"כף מייפל טבעי"},{"kind":"item","text":"מיץ לימון מחצי לימון"},{"kind":"item","text":"כפית שמן שומשום"},{"kind":"item","text":"כפית ג׳ינג׳ר טרי"},{"kind":"sublabel","text":"להגשה (לא לוותר):"},{"kind":"item","text":"כוסברה"},{"kind":"item","text":"בצל ירוק"},{"kind":"item","text":"פרוסות פלפל צ׳ילי אדום"},{"kind":"item","text":"שומשום (אפשר לקלות אותו)"}]'::jsonb, '["מדליקים תנור ל 180 מעלות.","חותכים את הכרובית לפרחים קטנים יחסית ומעבירים אותם לסיר עם מים רותחים ל 20 דקות, עד ריכוך קל.","מסננים ומעבירים את פרחי הכרובית לתבנית לתנור, מרססים בשמן זית ומכניסים לתנור ל 20 עד 25 דקות.","בינתיים מכינים את הרוטב בקערה נפרדת.","כשהכרובית מוכנה מניחים אותה על צלחת הגשה ושופכים מעל את הרוטב.","מפזרים כוסברה, בצל ירוק, צ׳ילי חריף ושומשום."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-04-12T00:00:00Z'::timestamptz)
