values ('d8e8f7ef-4ab0-57f8-8a72-4f2f3224b834', 'cinnamon-maple-hazelnut-muffins', null, 'מאפינס קינמון, מייפל ואגוזי לוז', 'מאפינס מקמח כוסמין עם מייפל, יוגורט וקינמון, ומעליהם קראמבל אגוזי לוז. יוצאים רכים וממלאים את כל הבית בריח מדהים.', '2025-10-05'::date, 'מאפים', array['צמחוני']::text[], 'לא צוין', null, '12 יחידות', '648566a2-4220-5231-8b61-acfe94f95cdf', '/media/client/recipes/cinnamon-maple-hazelnut-muffins.webp', 'מאפין קינמון עם קראמבל אגוזי לוז בתבנית, צילום מקרוב', 'מאפינס מקמח כוסמין 80% שעושים ריח וואו בכל הבית. אין על מאפינס, זה תמיד מביא לי ווייב חורפי, עשיר ומנחם.

אני מזמינה גם אתכם לעשות לעצמכם ריח של קינמון בכל הבית.', '[{"kind":"item","text":"ביצה L"},{"kind":"item","text":"1/3 כוס מייפל טבעי"},{"kind":"item","text":"200 גרם יוגורט 3%"},{"kind":"item","text":"כפית תמצית וניל"},{"kind":"item","text":"כוס קמח כוסמין 80%"},{"kind":"item","text":"כפית אבקת אפייה"},{"kind":"item","text":"כפית קינמון"},{"kind":"item","text":"40 גרם אגוזי לוז טחונים או אגוזים אחרים"},{"kind":"sublabel","text":"לקראמבל:"},{"kind":"item","text":"חופן אגוזי לוז קצוצים"},{"kind":"item","text":"כפית סוכר חום"},{"kind":"item","text":"כפית קינמון"},{"kind":"item","text":"קצת תמצית וניל"}]'::jsonb, '["מחממים תנור ל180 מעלות.","מוסיפים לקערה את הביצה, המייפל, היוגורט והוניל ומערבבים היטב בעזרת מטרפה.","מוסיפים את היבשים: קמח, אבקת אפייה וקינמון, ומערבבים לאיחוד.","מוסיפים את אגוזי הלוז ומאחדים. זהו, לא מערבבים מעבר לזה.","יוצקים כף גדושה או כף גלידה מהבלילה למנג''טים משומנים של קאפקייקס, ומוסיפים מעל כל אחד כפית מתערובת אגוזי הלוז.","אופים כ20 דקות ואוכלים בהנאה."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2025-10-05T00:00:00Z'::timestamptz)
