values ('be5d51fe-a7b1-586c-8b0f-3de64752af3d', 'colorful-chia-pudding', null, 'פודינג צ''יה צבעוני', 'פודינג צ''יה בשלוש גרסאות צבעוניות: קקאו, פטל וספירולינה. חמש דקות עבודה בערב, ובבוקר מחכה לכם מעדן מזין וקר מהמקרר.', '2026-01-11'::date, 'בוקר', array['קל ומהיר', 'צמחוני']::text[], '5 דקות', 5, 'מנה אחת', '002ff519-15b9-5557-8dd6-db76d2cf5df1', '/media/client/recipes/colorful-chia-pudding.webp', 'שלוש כוסות פודינג צ''יה בצבעי חום, ורוד וכחול על שולחן שיש', 'פודינג צ''יה הוא אחד הדברים הכי קלים שאני מכינה, וגם אחד הכי יפים. חמש דקות עבודה בערב, ובבוקר מחכה לי מעדן טעים, מזין וקר מהמקרר.

אני אוהבת להכין קופסה עם הפודינג לכל השבוע, לשמור במקרר ולשחק עם התוספות בכל פעם מחדש. ככה אף בוקר לא מרגיש אותו דבר.

הכמויות כאן הן למנה אחת, ואני ממליצה להכפיל.', '[{"kind":"item","text":"2 כפות זרעי צ''יה"},{"kind":"item","text":"2 כפות שיבולת שועל"},{"kind":"item","text":"1/3 כוס חלב (לבחירתכם)"},{"kind":"item","text":"תמצית וניל"},{"kind":"item","text":"100 גרם יוגורט לבחירתכם"},{"kind":"item","text":"כפית מייפל טבעי / דבש / סילאן"},{"kind":"item","text":"תוספת לבחירתכם"},{"kind":"sublabel","text":"התוספות שאני שיחקתי איתן:"},{"kind":"item","text":"פודינג קקאו: אבקת שוקומאקה, בננה, שוקולד מריר מגורד"},{"kind":"item","text":"פודינג ורוד: אבקת פטל, גרנולה"},{"kind":"item","text":"פודינג כחול: אבקת ספירולינה, אוכמניות, חמאת בוטנים טבעית"}]'::jsonb, '["מערבבים את כל הרכיבים בכוס או בקערה.","שומרים במקרר שעה לפחות או לילה שלם.","לפני האכילה מוסיפים טופינג לבחירתכם."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-01-11T00:00:00Z'::timestamptz)
