values ('6f2e73ab-d2d3-570b-8a22-e05fcdc876f2', 'corn-ribs', null, 'צלעות תירס בתנור', 'צלעות תירס אפויות בתנור עם שמן זית, פפריקה וצ׳ילי, יוצאות שחומות וקריספיות ומוגשות לצד רוטב יוגורט קר. נשנוש ממכר שמתאים גם כמנת פתיחה.', '2026-07-05'::date, 'חטיפים', array['צמחוני', 'ללא גלוטן', 'קל ומהיר']::text[], 'לא צוין', null, null, '20559790-abb2-57be-845e-b154b5db1258', '/media/client/recipes/corn-ribs.webp', 'צלחת מלאה בצלעות תירס אפויות עם פרמזן וקערית רוטב יוגורט', 'זה הנשנוש הכי כיפי וקל שיש אצלי בבית. צלעות תירס שנכנסות לתנור עם שמן זית ותיבול טוב, ויוצאות שחומות וקריספיות.

אני אוהבת להגיש אותן כמנת פתיחה, כתוספת לארוחה או סתם ככה מול הטלוויזיה, תמיד לצד רוטב יוגורט קר. מזהירה אתכם מראש: זה ממכר.', '[{"kind":"item","text":"4 קלחי תירס"},{"kind":"item","text":"4 כפות שמן זית"},{"kind":"item","text":"כפית מלח גס"},{"kind":"item","text":"כפית צ׳ילי גרוס"},{"kind":"item","text":"כפית פפריקה מתוקה"},{"kind":"item","text":"כפית אבקת שום גבישי"},{"kind":"sublabel","text":"לרוטב:"},{"kind":"item","text":"יוגורט יווני"},{"kind":"item","text":"כפית פפריקה"},{"kind":"item","text":"מיץ לימון מחצי לימון טרי"},{"kind":"item","text":"1-2 שיני שום כתושות"},{"kind":"item","text":"צ׳ילי גרוס"}]'::jsonb, '["חותכים את התירסים לחצאים בזהירות עם סכין גדולה. מניחים את החצאים בעמידה על קרש חיתוך, ואז כל חצי חוצים לאורך וחותכים לרבעים.","מעבירים את צלעות התירס לקערה גדולה, מוסיפים שמן זית, מתבלים ומערבבים היטב כך שכל צלע תירס מצופה בתיבול.","מחממים תנור ל 180 מעלות, מניחים את צלעות התירס על נייר אפייה ומכניסים לתנור ל 25-30 דקות עד שהתירס מעט קריספי ושחום.","מקשטים בפטרוזיליה ופרמזן ומגישים לצד הרוטב."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-07-05T00:00:00Z'::timestamptz)
