values ('627269b5-301e-5c7f-8cd5-6000d756f3c8', 'crispy-rice-tuna-salad', null, 'סלט אורז קריספי עם טונה ואבוקדו', 'סלט אורז קריספי מהתנור עם טונה, אבוקדו ומלפפון, ברוטב סויה, ג''ינג''ר ולימון. הדרך הכי טעימה לנצל שאריות אורז מהמקרר.', '2025-10-19'::date, 'סלטים', array['עתיר חלבון']::text[], 'לא צוין', null, null, '4ca6f89e-f2b2-503d-8cba-6a4e1d811fe1', '/media/client/recipes/crispy-rice-tuna-salad.webp', 'קערת סלט אורז קריספי עם אבוקדו ובצל סגול על שולחן עץ', 'המתכון הזה הוא אחת מהארוחות האהובות עליי, בדיוק בשביל הרגעים שאני לא יודעת מה לעשות עם שאריות האורז שנשארו במקרר.

האורז נכנס לתנור ויוצא קריספי ושחום, ונפגש עם ירקות טריים, טונה ורוטב סויה, לימון וג''ינג''ר. יוצא כל כך שווה וטעים.', '[{"kind":"item","text":"שאריות אורז, בערך 1.5 כוסות אורז מבושל או חצי כוס אורז לפני בישול"},{"kind":"item","text":"תרסיס שמן זית"},{"kind":"item","text":"כף סויה"},{"kind":"sublabel","text":"לסלט:"},{"kind":"item","text":"1 מלפפון"},{"kind":"item","text":"1/2 אבוקדו"},{"kind":"item","text":"בצל סגול"},{"kind":"item","text":"בצל ירוק"},{"kind":"item","text":"כוסברה"},{"kind":"sublabel","text":"לטונה:"},{"kind":"item","text":"קופסת טונה במים"},{"kind":"item","text":"כפית מיונז לייט"},{"kind":"item","text":"כף סויה"},{"kind":"item","text":"כפית סרירצה (לאוהבי החריף)"},{"kind":"sublabel","text":"לרוטב:"},{"kind":"item","text":"2 כפות סויה"},{"kind":"item","text":"כף חומץ אורז"},{"kind":"item","text":"מיץ לימון מחצי לימון טרי"},{"kind":"item","text":"כף מייפל טבעי"},{"kind":"item","text":"כפית ג''ינג''ר טרי מגורד"},{"kind":"item","text":"1/2 כפית שמן שומשום"}]'::jsonb, '["מחממים תנור ל200 מעלות.","מעבירים את האורז המבושל לתבנית, מרססים שמן זית, מוסיפים סויה, מערבבים ומשטחים על התבנית בעזרת כף.","מכניסים לתנור ל20-25 דקות עד שהאורז משחים ונהיה קריספי. ממליצה לפתוח את התנור ולערבב את האורז מדי פעם.","בינתיים חותכים את הירקות: את המלפפון מומלץ לחתוך לצורת חצי ירח, וכך גם את האבוקדו, הבצל והכוסברה. מכינים את הטונה ומסדרים הכל בקערה.","מערבבים את רכיבי הרוטב בצנצנת.","כשהאורז מוכן מעבירים אותו לקערה עם שאר רכיבי הסלט.","שופכים מעל את הרוטב, אפשר לפזר שומשום שחור, מערבבים היטב וזה הכי טעים שיש."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2025-10-19T00:00:00Z'::timestamptz)
