values ('5035a2d9-af50-55aa-871c-b8491de1f639', 'crispy-tofu-peanut-salad', null, 'סלט טופו קריספי עם אורז אפוי ורוטב בוטנים', 'סלט טופו קריספי עם אורז אפוי ורוטב חמאת בוטנים, ארוחה שלמה בקערה אחת עם הרבה חלבון, ירקות טריים ומרקם קראנצ׳י ממכר.', '2026-03-15'::date, 'סלטים', array['צמחוני', 'טבעוני', 'עתיר חלבון']::text[], 'לא צוין', null, null, 'bed82930-f6c6-54ed-83cc-d56a90896333', '/media/client/recipes/crispy-tofu-peanut-salad.webp', 'קערת סלט טופו קריספי עם ירקות ובצל ירוק קצוץ', 'סלט טופו קריספי עם קריספי רייס ורוטב בוטנים חלום, וזו ההתמכרות הבאה שלכם. סלט שהוא ארוחה שלמה: מהיר, קל, טעים ומלא בחלבון.

האורז נאפה בתנור עד שהוא משחים ונהיה פריך, הטופו מתפורר ונאפה לצידו, ואז הכל נפגש בקערה עם ירקות טריים ורוטב חמאת בוטנים קרמי.', '[{"kind":"item","text":"1 כוס אורז לאחר בישול (1/2 כוס לפני בישול)"},{"kind":"item","text":"כף סויה"},{"kind":"item","text":"תרסיס שמן זית"},{"kind":"sublabel","text":"לטופו קריספי:"},{"kind":"item","text":"300 גרם טופו"},{"kind":"item","text":"2 כפות קורנפלור"},{"kind":"item","text":"כפית פפריקה"},{"kind":"item","text":"כף סויה"},{"kind":"item","text":"שמן זית"},{"kind":"sublabel","text":"לסלט:"},{"kind":"item","text":"רבע כרוב חתוך דק (לבן או סגול)"},{"kind":"item","text":"1 גזר חתוך לג׳וליאנים"},{"kind":"item","text":"חצי כוס אדממה"},{"kind":"item","text":"צרור בצל ירוק"},{"kind":"item","text":"חופן כוסברה"},{"kind":"sublabel","text":"לרוטב:"},{"kind":"item","text":"2 כפות חמאת בוטנים טבעית"},{"kind":"item","text":"2 כפות סויה"},{"kind":"item","text":"כף מייפל טבעי"},{"kind":"item","text":"מיץ לימון מחצי לימון טרי"},{"kind":"item","text":"1 שן שום"},{"kind":"item","text":"2 כפות מים"}]'::jsonb, '["מחממים תנור ל 200 מעלות.","משטחים את האורז המבושל על תבנית עם נייר אפייה, מוסיפים סויה, מרססים בשמן זית ומכניסים לתנור ל 20 דקות עד שהאורז משחים.","לטופו קריספי: סופגים את הטופו היטב בנייר סופג (זה מה שגורם לו להיות קריספי יותר) ומפוררים אותו לחתיכות גסות לתוך תבנית. מוסיפים קורנפלור, תבלינים, סויה ושמן זית, מערבבים היטב ומכניסים לתנור ל 15-20 דקות.","בינתיים חותכים את כל הירקות לסלט ומכינים את הרוטב.","כשהאורז מוכן מעבירים אותו לקערה, מוסיפים את הירקות ואת הטופו הקריספי, שופכים את הרוטב ומערבבים."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-03-15T00:00:00Z'::timestamptz)
