values ('e9e099ab-cf34-5ca1-8f64-68d961e6e0fe', 'crunchy-rainbow-quinoa-salad', null, 'סלט קינואה צבעוני וקראנצ׳י', 'סלט קינואה צבעוני עם כרוב סגול, מלפפון, גבינה בולגרית וגרעיני דלעת ברוטב לימוני. נשאר פריך וטרי במקרר יומיים ומושלם לארוז לעבודה.', '2026-02-15'::date, 'סלטים', array['צמחוני', 'ללא גלוטן']::text[], 'לא צוין', null, null, '37208aaf-0c16-568b-8749-b554a9a5e8fe', '/media/client/recipes/crunchy-rainbow-quinoa-salad.webp', 'קערה שחורה עם סלט קינואה וכרוב סגול לצד כפית זהב', 'הסלט הזה הוא מהסוג שאני מכינה בכמות גדולה בתחילת השבוע, כי הוא נשאר פריך וטרי במקרר גם אחרי יומיים.

קינואה, המון ירקות צבעוניים, גבינה בולגרית וגרעיני דלעת, והכל נפגש ברוטב לימוני עם קצת דבש וחרדל. אני אוהבת לארוז אותו בקערה ולקחת לעבודה או ללימודים, והוא מספיק משביע כדי להיות ארוחה שלמה.', '[{"kind":"item","text":"כוס קינואה מבושלת"},{"kind":"item","text":"1-2 מלפפונים חתוכים לקוביות"},{"kind":"item","text":"1/3 כרוב סגול חתוך דק"},{"kind":"item","text":"1/2 בצל סגול חתוך לפרוסות"},{"kind":"item","text":"פלפל שושקה או פלפל אחר, פרוס"},{"kind":"item","text":"חופן כוסברה או פטרוזיליה קצוצה"},{"kind":"item","text":"חופן נענע קצוצה"},{"kind":"item","text":"100 גרם בולגרית 5%"},{"kind":"item","text":"חופן גרעיני דלעת"},{"kind":"sublabel","text":"לרוטב:"},{"kind":"item","text":"3 כפות שמן זית"},{"kind":"item","text":"מיץ לימון מלימון שלם"},{"kind":"item","text":"כף חומץ בלסמי"},{"kind":"item","text":"כף דבש"},{"kind":"item","text":"כפית חרדל דיז׳ון"},{"kind":"item","text":"2 שיני שום כתושות"},{"kind":"item","text":"כפית מלח"},{"kind":"item","text":"חצי כפית פלפל שחור"}]'::jsonb, '["מבשלים את הקינואה לפי הוראות היצרן.","חותכים את הירקות.","מכינים את הרוטב בתחתית הקערה ומערבבים.","מוסיפים את הקינואה, הירקות, הבולגרית והגרעינים ומערבבים הכל היטב.","בתיאבון!"]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-02-15T00:00:00Z'::timestamptz)
