values ('50c2ef05-a13c-5de5-8b02-37210d6d31a4', 'date-brownies', null, 'בראוניז תמרים', 'בראוניז תמרים רך ופאדג׳י על בסיס קמח שיבולת שועל, שוקולד מריר וקקאו, בלי סוכר לבן. קל להכנה ומספיק מתוק לכל חשק.', '2026-07-19'::date, 'מתוקים', array['צמחוני']::text[], 'לא צוין', null, null, 'fd874142-5dfe-5cdf-8fc4-6bbd13d165c8', '/media/client/recipes/date-brownies.webp', 'יד אוחזת ריבוע בראוניז תמרים עם שוקולד צ׳יפס', 'מדובר בבראוניז מתמרים, טעים, קל, עם מרכיבים מעולים ומזינים.

וכן, אני אגיד את המשפט המעצבן: גם אם אתם לא אוהבים תמרים, עדיין כנראה שתאהבו את הבראוניז הזה.', '[{"kind":"item","text":"8-9 תמרי מגהול עסיסיים (השתמשתי בשל שרית)"},{"kind":"item","text":"1/3 כוס חלב סויה, שקדים או אחר"},{"kind":"item","text":"2 ביצים"},{"kind":"item","text":"60 גרם שוקולד מריר"},{"kind":"item","text":"1/4 כוס שמן זית"},{"kind":"item","text":"כוס קמח שיבולת שועל (טוחנים כוס ורבע שיבולת שועל דקה)"},{"kind":"item","text":"2 כפות גדושות קקאו איכותי"},{"kind":"item","text":"כפית אבקת סודה לשתיה"},{"kind":"item","text":"קורט מלח"},{"kind":"item","text":"אופציונלי לתוספות: חופן שוקולד צ׳יפס, שוקולד מריר קצוץ או אגוזים"},{"kind":"item","text":"מלח גס"}]'::jsonb, '["מניחים את התמרים במים חמים ל 10 דקות לריכוך.","מחממים תנור ל 170 מעלות.","טוחנים במעבד מזון את התמרים עם החלב עד למרקם חלק.","ממיסים את השוקולד עם השמן במיקרוגל בפולסים של 30 שניות להמסה מלאה.","בקערה גדולה מניחים את הביצים, את התמרים שטחנו ואת השוקולד המומס, וטורפים היטב.","מוסיפים את קמח שיבולת השועל, הסודה לשתיה, הקקאו וקורט המלח, ומערבבים לתערובת אחידה.","מעבירים לתבנית משומנת, מפזרים מעל שוקולד צ׳יפס ומלח גס, ומכניסים לתנור ל 20 דקות, עד שמכניסים קיסם והוא יוצא מעט לח ולא יבש לגמרי.","מוציאים מהתנור, נותנים לבראוניז להצטנן ונהנים."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-07-19T00:00:00Z'::timestamptz)
