values ('20fb376c-7105-5da9-87cb-23fce9d73451', 'eggplant-carpaccio', null, 'קרפצ׳יו חציל בסגנון ים תיכוני', 'מנת פתיחה ים תיכונית של חציל קלוי ומעוך, עם בצל סגול, כוסברה, צנוברים, טחינה גולמית וסילאן. פשוטה להכנה ומרשימה על כל שולחן חגיגי.', '2025-08-24'::date, 'סלטים', array['צמחוני', 'טבעוני', 'ללא גלוטן']::text[], 'לא צוין', null, null, '13d76bff-9586-54b9-83d7-4148c6705229', '/media/client/recipes/eggplant-carpaccio.webp', 'מגש אובלי של קרפצ׳יו חציל מכוסה בירקות קצוצים וצנוברים', 'קרפצ׳יו חציל בסגנון ים תיכוני הוא אחד המתכונים שמלווים אותי כבר כמה שנים טובות, והוא מגיע אצלי לשולחן בכל ארוחה חגיגית. מנה מרשימה, פשוטה, וממש קלה להכנה.

זאת התוספת המושלמת לכל ארוחה, בין אם זו ארוחת חג, ארוחת שישי או סתם מנת פתיחה מפנקת. מניחים במרכז השולחן, טובלים ונהנים מכל ביס.', '[{"kind":"item","text":"2 חצילים (מומלץ בלאדי)"},{"kind":"item","text":"בצל סגול קצוץ"},{"kind":"item","text":"גבעול בצל ירוק קצוץ"},{"kind":"item","text":"חצי פלפל קצוץ / עגבניה"},{"kind":"item","text":"כוסברה"},{"kind":"item","text":"פלפל ירוק חריף פרוס לטבעות"},{"kind":"item","text":"חופן צנוברים קלויים"},{"kind":"item","text":"3-4 כפות שמן זית"},{"kind":"item","text":"3 כפות טחינה גולמית"},{"kind":"item","text":"זילוף סילאן"},{"kind":"item","text":"מלח גס"}]'::jsonb, '["מחוררים מעט את החציל עם מזלג וקולים אותו בתנור על 190 מעלות למשך 40 דקות.","חוצים את החציל במרכז ומניחים במסננת להוצאת הנוזלים עד שהחציל מתקרר, מעבירים לקרש חיתוך ומסירים את הקליפה בקלות.","קוצצים ומועכים את החציל היטב ומשטחים על צלחת רחבה.","מפזרים מעל את הבצל הסגול, הבצל הירוק, הפלפל, הכוסברה, הצנוברים והפלפל החריף.","מזלפים מעל שמן זית, טחינה גולמית, סילאן ומלח גס.","מגישים עם כל בסיס שאוהבים, ובתיאבון."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2025-08-24T00:00:00Z'::timestamptz)
