values ('a28117e3-e2c6-575a-8a63-36c4d12ad1b7', 'flourless-brownies', 'flourless-brownies', 'בראוניז פאדג׳ שוקולד ללא תוספת סוכר', 'בראוניז פאדג׳ שוקולד ללא קמח וללא תוספת סוכר, מחמישה מרכיבים בלבד. מרקם רך ועשיר שמתקבל אחרי קירור טוב במקרר.', '2026-05-03'::date, 'מתוקים', array['צמחוני', 'ללא גלוטן']::text[], 'לא צוין', null, null, '025c9878-8067-53b9-8018-a89d81fb01f4', '/media/client/recipes/flourless-brownies.webp', 'יד מחזיקה ריבוע בראוניז מאובק בלבן מעל התבנית', 'פאדג׳ שוקולד ללא תוספת סוכר, והכי טעים בעולם. את המתכון הזה יצרתי עבור אבא של בן הזוג שלי, שגילו לו לאחרונה סוכרת, ולמה שלא אשתף גם אתכם?

יצא פשוט טעים וכל כך פשוט להכנה, חמישה מרכיבים והתנור עושה את השאר.', '[{"kind":"item","text":"200 גרם שוקולד מריר (השתמשתי ב 70% קקאו)"},{"kind":"item","text":"100 גרם חמאה חתוכה לקוביות"},{"kind":"item","text":"3/4 כוס סוויטאנגו"},{"kind":"item","text":"4 ביצים L"},{"kind":"item","text":"2 כפות אבקת קקאו"},{"kind":"item","text":"קורט מלח"}]'::jsonb, '["מחממים תנור ל 170 מעלות.","ממיסים בפולסים במיקרוגל או בסיר קטן את השוקולד עם החמאה, עד מרקם חלק.","מוסיפים את הממתיק לתערובת השוקולד ומערבבים היטב.","מוסיפים את הביצים אחת אחת וטורפים היטב אחרי כל ביצה, עד שהיא נטמעת לחלוטין והתערובת הופכת סמיכה ומבריקה.","מוסיפים את הקקאו ואת קורט המלח ומערבבים היטב להטמעה.","יוצקים לתבנית משומנת עם נייר אפייה ואופים במשך 20-25 דקות. לא לאפות יותר מדי, המרכז צריך להישאר מעט רך והשוליים יציבים.","לא לוותר על השלב הזה: מכניסים למקרר ל 3 שעות לפחות לפני החיתוך. זה מה שיוצר את המרקם. תהנו!"]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-05-03T00:00:00Z'::timestamptz)
