values ('580e0633-7b50-57ce-8941-bd900c0cd495', 'green-goddess-salad', null, 'סלט גרין גודס הוויראלי', 'גרסה ביתית לסלט הגרין גודס הוויראלי: כרוב לבן, מלפפון ובצל ירוק ברוטב קרמי של תרד, בזיליקום, אבוקדו ויוגורט. מוכן בעשר דקות.', '2026-01-18'::date, 'סלטים', array['קל ומהיר', 'צמחוני']::text[], '10 דקות', 10, null, '1cbdd87e-4d56-56dc-8069-dd71e7f51612', '/media/client/recipes/green-goddess-salad.webp', 'קערת נירוסטה עם סלט גרין גודס וטורטיות קריספיות', 'סלט הגרין גודס הוויראלי מהטיקטוק, בגרסה שלי, ואין לי מושג איך לא הכנתי אותו קודם.

קריספי, מרענן, משביע ומפוצץ בטעמים. הקטע הוא שזה סלט שמרגיש לגמרי כמו ארוחה. כל מה שצריך זה 10 דקות מזמנכם, והוא נשמר מעולה במקרר.', '[{"kind":"item","text":"1/2 כרוב לבן קצוץ"},{"kind":"item","text":"2 מלפפונים חתוכים לקוביות"},{"kind":"item","text":"בצל ירוק קצוץ"},{"kind":"sublabel","text":"לרוטב:"},{"kind":"item","text":"כוס עלי תרד"},{"kind":"item","text":"3/4 כוס בזיליקום"},{"kind":"item","text":"3-4 שיני שום"},{"kind":"item","text":"1/2 בצל שאלוט או 1/4 בצל סגול"},{"kind":"item","text":"2 כפות שמן זית"},{"kind":"item","text":"1/2 אבוקדו"},{"kind":"item","text":"200 גרם יוגורט טבעי לבחירתכם (העדפתי יוגורט טבעי 3%)"},{"kind":"item","text":"מיץ לימון מלימון שלם"},{"kind":"item","text":"כפית גדושה דבש"},{"kind":"item","text":"כפית שטוחה מלח, חצי כפית פלפל שחור"},{"kind":"sublabel","text":"להגשה:"},{"kind":"item","text":"נאצוס או טורטיה קריספית מהתנור"}]'::jsonb, '["קוצצים את הכרוב, המלפפון והבצל הירוק ומעבירים לקערה.","בבלנדר טוחנים את כל רכיבי הרוטב עד מרקם חלק. טועמים, בודקים אם משהו חסר ומתבלים לפי הצורך.","שופכים את הרוטב על הסלט ומערבבים היטב.","אוכלים עם נאצוס, טורטיה קריספית או פיתה קריספית."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-01-18T00:00:00Z'::timestamptz)
