values ('ac67a788-ab1c-584e-8e50-0313b0caa1df', 'hearty-lentil-soup', null, 'מרק עדשים עשיר ומנחם', 'מרק עדשים חורפי עם המון ירקות, עלי סלרי וכוסברה. סיר אחד פשוט שיוצא משביע, מזין ומנחם בדיוק כשמתחשק משהו חם.', '2025-10-12'::date, 'מרקים', array['צמחוני', 'טבעוני', 'ללא גלוטן']::text[], 'לא צוין', null, null, '70f5fa5e-606f-5c92-8f66-55aa2fbfd6d3', '/media/client/recipes/hearty-lentil-soup.webp', 'קערת מרק עדשים סמיכה עם כף זהובה מונחת על מפית', 'איך אני אוהבת מרק עדשים ומרקים על בסיס קטניות, עם מלא ירקות ועשבי תיבול. זה משביע, מזין, מנחם וכל כך טעים, בדיוק מה שמתאים לימים הקרים.', '[{"kind":"item","text":"2 כפות שמן זית"},{"kind":"item","text":"2 בצלים קצוצים"},{"kind":"item","text":"4-5 שיני שום פרוסות דק"},{"kind":"item","text":"גבעול סלרי קצוץ"},{"kind":"item","text":"3 גזרים חתוכים לקוביות"},{"kind":"item","text":"קישוא חתוך לקוביות"},{"kind":"item","text":"עלי סלרי"},{"kind":"item","text":"חופן כוסברה או פטרוזיליה"},{"kind":"item","text":"כפית שורש פטרוזיליה מגורד (לא חובה)"},{"kind":"item","text":"1 כוס עדשים, לשטוף היטב ולסנן"},{"kind":"item","text":"כפית מלח"},{"kind":"item","text":"חצי כפית כורכום"},{"kind":"item","text":"חצי כפית כמון"},{"kind":"item","text":"פלפל שחור"},{"kind":"item","text":"שום גבישי"},{"kind":"item","text":"10 כוסות מים רותחים"}]'::jsonb, '["קוצצים את הבצל, השום, הגזרים, הסלרי והקישוא לקוביות.","בסיר גדול מטגנים את הבצל, הגזר, הסלרי והשום במשך כמה דקות עד שהם מתרככים ונצרבים, ואז מוסיפים את הקישוא.","מוסיפים את עלי הסלרי והכוסברה.","מוסיפים את העדשים, אחרי שטיפה וסינון.","מתבלים במלח, פלפל, כמון, כורכום ושום ומערבבים היטב.","מוסיפים את המים הרותחים, מערבבים, מביאים לרתיחה, מכסים את הסיר ומבשלים על אש בינונית 35-40 דקות."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2025-10-12T00:00:00Z'::timestamptz)
