values ('cc89e410-070e-50d7-824a-457f46cad11a', 'homemade-granola', 'homemade-granola', 'גרנולת פצפוצי אורז ביתית', 'גרנולה ביתית מפצפוצי אורז עם אגוזים, גרעינים וחמוציות, מתוקה בסילאן בלבד. עשר דקות עבודה, כמה דקות בתנור, וצנצנת שנשמרת עד חודש.', '2025-08-17'::date, 'בוקר', array['קל ומהיר', 'צמחוני', 'טבעוני']::text[], '10 דקות', 10, null, 'ea3e2dd1-d77e-5111-859c-b3c1aa92bd7b', '/media/client/recipes/homemade-granola.webp', 'גרנולה פריכה בכוס זכוכית שקופה על אדן חלון', 'למה לקנות גרנולה בסופר, כשאפשר להכין אותה בבית בעשר דקות, בצורה הרבה יותר מאוזנת ועם הרבה פחות סוכר? אחרי שמתחילים להכין אותה ומבינים כמה זה פשוט, כבר לא חוזרים לקנות.

גרנולת פצפוצי האורז הזאת היא הטעימה ביותר שאני מכירה, והכי קלה להכנה. בדיוק מה שאני אוהבת להכין בתחילת שבוע חדש, כדי שתחכה לי צנצנת טובה במטבח.', '[{"kind":"item","text":"3 כוסות פצפוצי אורז"},{"kind":"item","text":"1/2 כוס של אגוזים וגרעינים, אפשר לשלב מכל סוג. אני הוספתי 1/4 כוס גרעיני דלעת ו-1/4 כוס שקדים פרוסים"},{"kind":"item","text":"2 כפות חמוציות ללא תוספת סוכר"},{"kind":"item","text":"1 כפית קינמון"},{"kind":"item","text":"3 כפות סילאן"}]'::jsonb, '["מחממים תנור ל-180 מעלות.","מערבבים את כל הרכיבים יחד בקערה גדולה.","משטחים את תערובת הגרנולה על תבנית עם נייר אפייה.","מכניסים לתנור ל-5-6 דקות (פצפוצי האורז נשרפים מהר), מוציאים מהתנור ונותנים לגרנולה להתקרר מעט.","מעבירים לצנצנת אטומה, נשמרת עד חודש."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2025-08-17T00:00:00Z'::timestamptz)
