values ('198032d6-3bd8-5b42-8f07-7f8ddbd6679c', 'kale-crispy-chickpea-salad', null, 'סלט קייל עם חומוס קריספי ובצל מוחמץ', 'סלט קייל מעוסה עם חומוס קריספי מהתנור, מלפפון, בצל מוחמץ ורוטב חרדל וטחינה. עשיר בסיבים, קראנצי ומשביע לארוחה קלה.', '2025-11-16'::date, 'סלטים', array['צמחוני', 'ללא גלוטן']::text[], 'לא צוין', null, null, '3acf8320-167e-515c-84d4-a32c0db7396a', '/media/client/recipes/kale-crispy-chickpea-salad.webp', 'סלט קייל מעורבב בקערה לבנה על מפה משובצת צהובה', 'קראתי לו סלט של בריאות ולא סתם. יש בו הרבה סיבים תזונתיים שתורמים לתחושת שובע, נוגדי חמצון מהירוקים, מהעלים ומהבצל המוחמץ, וגם ויטמין K, חומצה פולית וויטמין C בזכות הקייל.

החומוס הקריספי מהתנור הוא הכוכב כאן, והרוטב עם החרדל, הדבש והטחינה מחבר את הכל. בתיאבון!', '[{"kind":"item","text":"צרור עלי קייל (ללא גבעולים, חתוכים לרצועות) + כף שמן זית + מעט לימון"},{"kind":"item","text":"1 מלפפון"},{"kind":"item","text":"בצל מוחמץ או 1/2 בצל סגול רגיל"},{"kind":"item","text":"חופן כוסברה"},{"kind":"item","text":"צרור בצל ירוק"},{"kind":"sublabel","text":"לחומוס קריספי:"},{"kind":"item","text":"200 גרם גרגרי חומוס מבושלים (כוס וחצי)"},{"kind":"item","text":"כף שמן זית"},{"kind":"item","text":"כפית פפריקה, כפית שום גבישי"},{"kind":"sublabel","text":"לרוטב:"},{"kind":"item","text":"2-3 כפות שמן זית"},{"kind":"item","text":"מיץ לימון מחצי לימון טרי"},{"kind":"item","text":"כפית חרדל דיז''ון"},{"kind":"item","text":"כפית דבש"},{"kind":"item","text":"שן שום כתושה"},{"kind":"item","text":"כפית טחינה גולמית"},{"kind":"item","text":"מלח, פלפל שחור"}]'::jsonb, '["שוטפים היטב את עלי הקייל, חותכים לרצועות ומניחים בקערה. מוסיפים מעט שמן זית ולימון ומתחילים לעסות את העלים 2-3 דקות, זה מרכך אותם ומוציא את המרירות.","מחממים תנור ל 190 מעלות, מניחים את גרגרי החומוס על תבנית עם נייר אפיה, מוסיפים שמן זית ותיבול ומכניסים לתנור ל 20 דקות.","בינתיים מכינים את הרוטב. מוסיפים את כל רכיבי הסלט לקערה, וכשהחומוס מוכן וקריספי מוסיפים גם אותו.","שופכים את הרוטב ומערבבים היטב."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2025-11-16T00:00:00Z'::timestamptz)
