values ('13dc9679-983e-5d50-847f-4f4d9c3fda5d', 'lemon-garlic-greens', null, 'הירוקים של אייל שני', 'ירקות ירוקים שנחלטים כמה דקות בלבד ונשארים פריכים, ומתערבבים ברוטב שום, לימון ושמן זית. תוספת קרה שנעלמת מהצלחת.', '2025-11-23'::date, 'סלטים', array['קל ומהיר', 'צמחוני', 'טבעוני', 'ללא גלוטן', 'דל פחמימה']::text[], 'לא צוין', null, null, 'eada79e6-1f4c-5f66-8c57-c8d54e2015a5', '/media/client/recipes/lemon-garlic-greens.webp', 'ערימת שעועית ואפונת שלג ירוקות מונחת על נייר לבן', 'זו הדרך הכי כיפית וטעימה לאכול את הירוקים שלכם, וזה גם נשנוש שיוצא קראנצי, טעים ומזין. החליטה הקצרה במים רותחים שומרת על הקשיחות של הירקות, ומיד אחריה אמבט קרח שעוצר את הבישול.

הרוטב הוא פשוט שום, גרידת לימון, מיץ לימון, מלח גס ושמן זית, ואוכלים את הכל קר. בתיאבון!', '[{"kind":"item","text":"שעועית טריה"},{"kind":"item","text":"אפונת שלג טריה"},{"kind":"item","text":"ברוקומיני / ברוקולי מיני"},{"kind":"item","text":"או כל ירוקים בסגנון שיתאימו"},{"kind":"item","text":"4-5 שיני שום כתושות"},{"kind":"item","text":"גרידת לימון מלימון שלם"},{"kind":"item","text":"מיץ לימון מלימון שלם"},{"kind":"item","text":"כף מלח גס"},{"kind":"item","text":"4 כפות שמן זית"}]'::jsonb, '["מרתיחים סיר עם מים וחולטים את הירוקים במים הרותחים 3-4 דקות בלבד, אנחנו רוצים שהם ישמרו על הקשיחות שלהם. בינתיים כבר מארגנים קערה גדולה עם קרח ומים קרים.","מעבירים את הירוקים ישר מהמים הרותחים לקערה עם הקרח לעצירת הבישול.","בינתיים בקערה גדולה שמים בתחתית את השום, גרידת הלימון, מיץ הלימון, המלח ושמן הזית ומערבבים היטב. אני עירבבתי בעזרת מטרפה.","מעבירים את הירוקים ממי הקרח לתוך הקערה הגדולה ומערבבים טוב טוב בעזרת הידיים, כך שכל הירוקים יהיו עטופים ברוטב.","מעבירים לצלחת הגשה, מומלץ לפזר מעל עוד קצת גרידת לימון ומלח גס. אוכלים קר."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2025-11-23T00:00:00Z'::timestamptz)
