values ('1c99a460-ee73-5069-8d2c-75a5c10d8f7e', 'light-cheese-lasagna', null, 'לזניית גבינות רזות', 'לזניה ביתית עם רוטב עגבניות ותערובת של קוטג'', ריקוטה ובולגרית רזות. עשירה בחלבון, קלה להכנה ומושלמת לארוחת ערב.', '2025-12-28'::date, 'ערב', array['צמחוני', 'עתיר חלבון']::text[], 'לא צוין', null, null, '5bc11290-8465-5e04-8561-16d116a6acd2', '/media/client/recipes/light-cheese-lasagna.webp', 'פרוסת לזניה מוגשת בצלחת מעוטרת לצד התבנית עם עלי בזיליקום', 'איזה טעים זה לזניה. זו גרסה קלה להכנה ומפוצצת בחלבון, עם תערובת גבינות רזות ורוטב עגבניות ביתי.

היא הולכת לסגור לכם את הפינה לארוחת הערב הבאה, וגם מתאימה למי שרוצה להרשים באיזה בראנץ''.', '[{"kind":"item","text":"9 דפי לזניה (3 שכבות, 3 דפים בכל שכבה)"},{"kind":"sublabel","text":"לרוטב עגבניות:"},{"kind":"item","text":"כפית שמן זית"},{"kind":"item","text":"400 גרם רסק עגבניות מרוסקות ללא סוכר"},{"kind":"item","text":"2-3 שיני שום כתושות"},{"kind":"item","text":"כפית סילאן"},{"kind":"item","text":"כפית מלח, כפית פפריקה, חצי כפית פלפל שחור"},{"kind":"item","text":"חופן בזיליקום טרי"},{"kind":"sublabel","text":"לתערובת הגבינות:"},{"kind":"item","text":"250 גרם (גביע) קוטג'' 5%"},{"kind":"item","text":"200 גרם ריקוטה 5%"},{"kind":"item","text":"100 גרם בולגרית מעודנת 5%"},{"kind":"item","text":"2 פרוסות גבינה צהובה 9-15%"},{"kind":"sublabel","text":"לפיזור והקרמה בשכבה האחרונה:"},{"kind":"item","text":"30 גרם גבינה צהובה מגורדת (% לבחירתכם)"},{"kind":"item","text":"פרמזן מגורד"}]'::jsonb, '["מחממים תנור ל 180 מעלות.","מערבבים בקערה גדולה את כל הגבינות.","בסיר קטן מחממים שמן זית ומוסיפים את השום והתבלינים, מוסיפים את העגבניות, הסילאן והבזיליקום, מערבבים ומורידים מהגז.","בתבנית בינונית בונים את השכבות: שכבה ראשונה של 3 דפי לזניה, שכבת גבינות, שכבת רוטב עגבניות, שכבת דפי לזניה, שכבת גבינות, שכבת עגבניות, שכבת דפי לזניה ושכבת רוטב עגבניות אחרונה.","מפזרים מעל עוד גבינה צהובה ופרמזן.","מכניסים לתנור ל 30 דקות, עד שהגבינות משחימות והלזניה רכה וחמה."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2025-12-28T00:00:00Z'::timestamptz)
