values ('84839253-c713-537e-84ae-e747a419ab1c', 'maple-mustard-tofu-skewers', null, 'שיפודי טופו וירקות במרינדת מייפל וחרדל', 'שיפודי טופו וירקות במרינדת מייפל, לימון וחרדל דיז׳ון, נצלים בתנור או באיירפרייר. מנה טבעונית עשירה בחלבון שנראית מרשימה על השולחן.', '2026-05-10'::date, 'ערב', array['צמחוני', 'טבעוני', 'עתיר חלבון', 'ללא גלוטן']::text[], 'לא צוין', null, null, 'a4b727ef-840c-59b7-88f6-ce72d71b9531', '/media/client/recipes/maple-mustard-tofu-skewers.webp', 'מגש שיפודי טופו וירקות מפוזרים בכוסברה ובצל ירוק', 'שיפודי ירקות וטופו במרינדה עסיסית של מייפל, לימון וחרדל, שיוצרים ביס מושלם. זו מנה שלגמרי הופכת לכוכבת המרכזית על השולחן.

הטיפ שלי הוא לשים את הכרוב צמוד לטופו על השיפוד. הוא נצלה יפה, נעשה פריך בקצוות וסופג את כל הטעמים סביבו.', '[{"kind":"item","text":"חבילת טופו (300 גרם)"},{"kind":"item","text":"1/2 רבע כרוב לבן או סגול חתוך לריבועים רחבים (שכבות של כרוב)"},{"kind":"item","text":"1 זוקיני פרוס לחצאי עיגולים עבים"},{"kind":"item","text":"1 בצל סגול חתוך לפלחים"},{"kind":"sublabel","text":"למרינדת לימון מייפל:"},{"kind":"item","text":"4 כפות שמן זית"},{"kind":"item","text":"מיץ מחצי לימון גדול"},{"kind":"item","text":"1 כף חרדל דיז׳ון"},{"kind":"item","text":"2 כפות מייפל טבעי"},{"kind":"item","text":"2 שיני שום כתושות"},{"kind":"item","text":"כפית שטוחה מלח, מעט צ׳ילי גרוס"}]'::jsonb, '["חותכים את הטופו לקוביות.","מערבבים את כל רכיבי הרוטב בקערה. מניחים את קוביות הטופו בקופסה, מוזגים עליהן חצי מהרוטב ומשרים 15-20 דקות.","בינתיים חותכים את הירקות גס ומתחילים להרכיב את השיפודים.","משחילים על השיפוד לפי הסדר שאוהבים. ממליצה לשים את הכרוב צמוד לטופו, הוא נצלה טוב וסופג את הטעמים שלו.","את שארית הרוטב מורחים מעל השיפודים ועל הירקות, כך שכל ירק יהיה מצופה ברוטב. שומרים 1-2 כפות מהרוטב בצד לצלחות.","בתנור: מחממים ל 200 מעלות (טורבו), מסדרים את השיפודים על תבנית עם נייר אפייה וצולים כ 20 דקות. באמצע הזמן כדאי להפוך אותם פעם אחת כדי שיקבלו צבע מכל הצדדים.","בנינג׳ה או באיירפרייר: 180-200 מעלות על מצב גריל למשך 12-15 דקות, תלוי בעוצמה, עד שהירקות מתרככים ומשחימים והטופו מזהיב.","כשהשיפודים יוצאים מברישים אותם שוב בשאריות הרוטב ששמרנו, מפזרים כוסברה או פטרוזיליה ובצל ירוק. בתיאבון!"]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-05-10T00:00:00Z'::timestamptz)
