values ('0be7f10a-8d46-5554-8fa1-d2aa38a0d216', 'maple-pecan-spelt-cake', null, 'עוגת מייפל מקמח כוסמין עם קראסט פקאן', 'עוגת מייפל רכה מקמח כוסמין לבן, עם קראסט פקאן קינמון פריך ומייפל טבעי שנשפך מעל כשהיא עדיין חמה. מאוזנת יותר וקלה להכנה.', '2025-08-10'::date, 'מתוקים', array['צמחוני']::text[], 'לא צוין', null, null, 'fd358097-5677-5d2c-8f98-58352fc3bf8b', '/media/client/recipes/maple-pecan-spelt-cake.webp', 'עוגת מייפל פרוסה בתבנית אינגליש ופרוסה בצלחת עם מזלג', 'אין כמו עוגת מייפל. זאת עוגה מקמח כוסמין לבן עם קראסט פקאן קינמון, מאוזנת יותר וקלה להכנה.

הסוד הקטן שלה הוא המייפל שנשפך עליה כשהיא עדיין חמה ונספג פנימה, וזה בדיוק מה שהופך אותה לרכה כל כך.', '[{"kind":"item","text":"3 ביצים"},{"kind":"item","text":"1/3 כוס סוכר או תחליף סוכר (ממליצה על סוויטאנגו)"},{"kind":"item","text":"3 כפות מייפל טבעי"},{"kind":"item","text":"1/4 כוס שמן"},{"kind":"item","text":"1/3 כוס חלב סויה/שקדים/רגיל"},{"kind":"item","text":"כפית תמצית וניל"},{"kind":"item","text":"כוס ורבע (180 גרם) קמח כוסמין לבן"},{"kind":"item","text":"שקית אבקת אפייה"},{"kind":"sublabel","text":"לקראסט פקאן:"},{"kind":"item","text":"30 גרם פקאן קצוץ (בערך חופן)"},{"kind":"item","text":"כפית סוכר חום"},{"kind":"item","text":"כפית קינמון"}]'::jsonb, '["מחממים תנור ל-180 מעלות.","טורפים בקערה את הביצים עם הסוכר במשך 2 דקות, ולאחר מכן מוסיפים את השמן, המייפל, החלב ותמצית הווניל ומערבבים היטב בעזרת מטרפה.","מוסיפים את הקמח ואבקת האפייה ומערבבים לאיחוד.","מעבירים לתבנית משומנת.","מערבבים בקערה נפרדת את הפקאנים הקצוצים עם הסוכר החום והקינמון ומפזרים מעל בלילת העוגה.","מכניסים לתנור ל-30 דקות, או עד שמכניסים קיסם והוא יוצא נקי.","שופכים על העוגה 2 כפות מייפל טבעי כשהיא עדיין חמה."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2025-08-10T00:00:00Z'::timestamptz)
