values ('8c24a660-5dfe-5be3-8a89-327d1d582a20', 'mini-broccoli-cheese-quiches', null, 'קיש ברוקולי וגבינות אישי ללא בצק', 'קישים אישיים בתבנית מאפינס בלי בצק: תחתית טורטיה פריכה ומילוי ביצים, קוטג׳ ובולגרית עם ברוקולי. פתרון קל לארוחת בוקר או ערב.', '2026-06-21'::date, 'מאפים', array['צמחוני', 'עתיר חלבון']::text[], 'לא צוין', null, '10-12 קישים', '7a4c32d3-c96a-59dc-84c9-3493dd607302', '/media/client/recipes/mini-broccoli-cheese-quiches.webp', 'צלחת עם קישים אישיים ברוקולי לצד סלט ירקות צבעוני', 'מהיום לא צריך בצק כדי להכין קיש מוצלח. במקום בצק אני קורצת עיגולים מטורטיות ודוחפת אותם לשקעי תבנית המאפינס, וזה עובד מושלם.

המילוי הוא ביצים עם קוטג׳, בולגרית ומוצרלה, עם המון פרחי ברוקולי. הקישים האישיים האלה סוגרים לי את הפינה לארוחת ערב או בוקר בקלי קלות.', '[{"kind":"item","text":"4-5 טורטיות (עדיף חיטה מלאה או כוסמין)"},{"kind":"item","text":"תרסיס שמן זית"},{"kind":"item","text":"1.5-2 כוסות פרחי ברוקולי קטנים (טריים או קפואים מופשרים) או כל ירק שמתאים לכם"},{"kind":"sublabel","text":"לתערובת הגבינות:"},{"kind":"item","text":"3 ביצים"},{"kind":"item","text":"200 גרם קוטג 5% (או ריקוטה)"},{"kind":"item","text":"100 גרם בולגרית 5%"},{"kind":"item","text":"50 גרם מוצרלה או גבינה צהובה מגורדת"},{"kind":"item","text":"מלח, פלפל, מעט שום גבישי"}]'::jsonb, '["מחממים תנור ל 180 מעלות.","לברוקולי: חולטים כמה דקות במים רותחים וסוחטים מהנוזלים. קוצצים גס.","בקערה מערבבים את הביצים, הגבינות והתבלינים לתערובת אחידה, מוסיפים את הברוקולי ומאחדים.","יוצרים את התחתית: בעזרת כוס רחבה או קורץ עוגיות, קורצים עיגולים מהטורטיות (בקוטר שגדול קצת משקעי המאפינס).","משמנים קלות את תבניות המאפינס, ודוחפים בעדינות עיגול טורטיה לכל שקע מאפינס.","מוזגים את הבלילה של הגבינות והברוקולי לתוך הטורטיות.","מכניסים לתנור למשך 20-25 דקות, עד שהגבינה מזהיבה והטורטיה נהיית מעט שחומה וקריספית."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-06-21T00:00:00Z'::timestamptz)
