values ('76ad3e29-5e99-533d-87f2-0daf36793510', 'oven-fried-rice-tofu', null, 'אורז מוקפץ בתנור עם ירקות וטופו', 'אורז מוקפץ שנאפה בתנור בכלי אחד עם טופו, גזר, אפונה וקישוא. בלי בלגן במטבח, יוצא משחים וקריספי בקצוות ומשביע מאוד.', '2025-11-09'::date, 'ערב', array['צמחוני', 'טבעוני', 'עתיר חלבון']::text[], 'לא צוין', null, null, '3448365c-65a1-5444-81df-004fcf295209', '/media/client/recipes/oven-fried-rice-tofu.webp', 'תקריב אורז מוקפץ בתנור עם קוביות טופו וירקות', 'הכל בכלי אחד, בלי כלים מיותרים ובלי בלגן במטבח. זו ארוחה מעולה ומהירה שהולכת לסגור לכם את הפינה השבוע, ואפשר כמובן לשחק עם הירקות ועם תוספת החלבון.

האורז יוצא מהתנור משחים ואפילו קצת קריספי בצדדים, וזה בעיניי החלק הכי טעים. בתיאבון!', '[{"kind":"item","text":"1 כוס אורז עגול / יסמין / בסמטי"},{"kind":"item","text":"300 גרם טופו חתוך לקוביות"},{"kind":"item","text":"1-2 גזרים קלופים חתוכים לקוביות"},{"kind":"item","text":"זוקיני / קישוא חתוך"},{"kind":"item","text":"כוס אפונה קפואה / תירס / אדממה"},{"kind":"item","text":"בצל לבן קצוץ"},{"kind":"item","text":"3 שיני שום פרוסות"},{"kind":"item","text":"1/4 כוס סויה"},{"kind":"item","text":"2 כפות סילאן"},{"kind":"item","text":"כפית שמן שומשום"},{"kind":"item","text":"כפית צ''ילי גרוס"},{"kind":"item","text":"2 כוסות מים רותחים"},{"kind":"sublabel","text":"לקישוט:"},{"kind":"item","text":"בצל ירוק, כוסברה, בוטנים"}]'::jsonb, '["מחממים תנור ל 200 מעלות.","בכלי מתאים לתנור או בסיר רחב מתאים לתנור שופכים את האורז, הירקות, הטופו והתיבול ומערבבים.","מוסיפים את המים הרותחים ומערבבים הכל יחד.","מכסים היטב את הכלי בעזרת אלומיניום או מכסה לסיר ומכניסים לתנור לחצי שעה.","לאחר חצי שעה מורידים את הכיסוי ואופים כ 20 דקות נוספות ללא כיסוי, עד שהאורז מוכן ומשחים ואפילו מעט קריספי בצדדים (הכי טעים!).","מומלץ לפזר מעל בצל ירוק, כוסברה ובוטנים."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2025-11-09T00:00:00Z'::timestamptz)
