values ('633827a6-7a7b-5667-8c6f-5c1b242bd0ad', 'oven-noodle-stir-fry', null, 'מוקפץ אטריות אורז וטופו בתנור בתבנית אחת', 'אטריות אורז, טופו וירקות שנאפים יחד בתבנית אחת ברוטב סויה וטריאקי, ארוחה מלאה ומנחמת בלי הקפצה ובלי ערימת כלים.', '2026-03-08'::date, 'ערב', array['צמחוני', 'טבעוני', 'עתיר חלבון']::text[], 'לא צוין', null, null, '238a0995-9bbd-53ca-8491-6024f669a39d', '/media/client/recipes/oven-noodle-stir-fry.webp', 'תבנית זכוכית מלאה באטריות אורז, טופו וברוקולי', 'מוקפץ עם אטריות אורז וטופו, הכל בתנור ובתבנית אחת. שמעתם נכון: ארוחה שלמה, מזינה וטעימה ברמות, בלי לשטוף כלים ובלי בלגן.

אני מסדרת הכל בתבנית, שופכת מעל את הרוטב ונותנת לתנור לעשות את העבודה. האטריות סופגות את הטעמים, הטופו משחים והירקות מתרככים בדיוק כמו במוקפץ במחבת.', '[{"kind":"item","text":"300 גרם טופו"},{"kind":"item","text":"200 גרם אטריות אורז"},{"kind":"item","text":"בצל סגול"},{"kind":"item","text":"גזר חתוך לג׳וליאנים"},{"kind":"item","text":"ברוקולי"},{"kind":"item","text":"פטריות"},{"kind":"item","text":"4-5 שיני שום חתוכות דק"},{"kind":"item","text":"תרסיס שמן זית"},{"kind":"sublabel","text":"לרוטב:"},{"kind":"item","text":"2 כוסות מים חמים"},{"kind":"item","text":"1/3 כוס סויה"},{"kind":"item","text":"2 כפות טריאקי"},{"kind":"item","text":"כף סילאן"},{"kind":"item","text":"כפית שמן שומשום"},{"kind":"item","text":"כפית צ׳ילי גרוס"}]'::jsonb, '["מחממים תנור ל 180 מעלות. חותכים את הטופו לקוביות ומייבשים בעזרת נייר סופג.","חותכים את כל הירקות.","מניחים בתבנית אטריות אורז, ירקות וטופו.","מערבבים בקערה את המים ורכיבי הרוטב ושופכים מעל התבנית.","מזלפים מעל עוד סילאן ומרססים בתרסיס שמן זית, לא לוותר על זה.","מכסים את התבנית בנייר אלומיניום או במכסה מתאים ומכניסים לתנור ל 25 דקות. לאחר 25 דקות מסירים את המכסה ומכניסים ל 20 דקות נוספות או עד שמשחים והאטריות מתרככות.","מוציאים מהתנור, מערבבים ומגישים."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-03-08T00:00:00Z'::timestamptz)
