values ('b07db503-ff7e-5282-8ad3-f6a0ff6c0934', 'peanut-butter-date-bark', null, 'חטיף תמרים עם חמאת בוטנים ושוקולד', 'משטח תמרים קפוא עם חמאת בוטנים, אגוזים, שוקולד מריר ומלח גס. מתוק טבעי שנשמר במקפיא ומוכן בכמה דקות עבודה בלבד.', '2026-04-05'::date, 'חטיפים', array['צמחוני', 'ללא גלוטן']::text[], 'לא צוין', null, null, '18e0d713-0800-56aa-8b6c-736b45f255ea', '/media/client/recipes/peanut-butter-date-bark.webp', 'משטח חטיף תמרים בשוקולד חתוך לריבועים על נייר אפייה', 'זה החטיף תמרים הכי ויראלי שיש, ובצדק. אי אפשר לטעות בשילוב של תמרים, חמאת בוטנים, שוקולד מריר ומלח גס.

אני מכינה אותו בכמה דקות עבודה, שומרת במקפיא וחותכת חתיכה בכל פעם שמתחשק משהו מתוק.', '[{"kind":"item","text":"10 תמרי מג׳הול"},{"kind":"item","text":"שקדים פרוסים, פקאנים, פיסטוקים או אגוזים קצוצים לבחירתכם"},{"kind":"item","text":"3 עד 4 כפות חמאת בוטנים טבעית"},{"kind":"item","text":"50 גרם שוקולד מריר מומס"},{"kind":"item","text":"קצת מלח גס"}]'::jsonb, '["חוצים את התמרים ומוציאים את הגלעינים.","מניחים על נייר אפייה כשהחלק הפתוח כלפי מעלה, קרובים אחד לשני.","מניחים מעליהם עוד נייר אפייה, ובעזרת כוס או מערוך מועכים אותם למשטח אחיד, לא מאוד דק.","מסירים את נייר האפייה העליון ומפזרים אגוזים, חמאת בוטנים, שוקולד מומס ומלח גס.","מכניסים למקפיא לשעה או שעתיים לפחות.","חותכים לחתיכות ושומרים במקפיא."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-04-05T00:00:00Z'::timestamptz)
