values ('3a9e6495-3dc8-5a94-85b6-577b8036636f', 'protein-pancakes', 'protein-pancakes', 'פנקייקים משיבולת שועל עתירי חלבון', 'פנקייקים רכים משיבולת שועל, בננה, ביצה ויוגורט מועשר בחלבון. חמש דקות הכנה, בלי קמח לבן, ומושלמים לבוקר נינוח עם פירות ומייפל.', '2025-08-03'::date, 'בוקר', array['קל ומהיר', 'צמחוני', 'עתיר חלבון']::text[], '5 דקות', 5, '10 פנקייקים', 'dad59b74-c571-57a2-8174-02952873c9a3', '/media/client/recipes/protein-pancakes.webp', 'מגדל פנקייקים בצלחת לבנה עם תאנים, בננה ואוכמניות', 'פנקייקים רכים וטעימים בגרסה בריאה יותר, עם שיבולת שועל ועשירים בחלבון. חמש דקות הכנה, ובול לבוקר כיפי של חג.

אני אוהבת להגיש אותם עם פירות טריים, זילוף מייפל וכל מה שיש בבית.', '[{"kind":"item","text":"1 בננה"},{"kind":"item","text":"ביצה"},{"kind":"item","text":"יוגורט וניל מועשר בחלבון"},{"kind":"item","text":"50 גרם שיבולת שועל"},{"kind":"item","text":"כפית תמצית וניל"},{"kind":"item","text":"כפית אבקת אפייה"}]'::jsonb, '["טוחנים את כל הרכיבים במיקסר או במעבד מזון, או מועכים היטב את הבננה ומערבבים בקערה את כל הרכיבים.","מרססים מעט שמן במחבת ומחממים.","יוצרים פנקייקים בעזרת כף גלידה, וכאשר נוצרות בועות על הפנקייק הופכים אותו לצד השני.","מוסיפים פירות לבחירה, מייפל ומה שתרצו."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2025-08-03T00:00:00Z'::timestamptz)
