values ('cb18e9a1-0ce1-562b-8034-da67129ec144', 'quinoa-lentil-labneh-salad', null, 'סלט קינואה ועדשים על מצע לאבנה', 'שחזור ביתי של סלט הספורטאיות: קינואה, עדשים שחורות והמון ירקות ועשבי תיבול על מצע לאבנה, עם טחינה גולמית מעל. סלט עשיר ומשביע.', '2026-06-14'::date, 'סלטים', array['צמחוני', 'עתיר חלבון', 'ללא גלוטן']::text[], 'לא צוין', null, '4 מנות', 'a1898246-98b5-5f91-8824-3ea7061ef6ad', '/media/client/recipes/quinoa-lentil-labneh-salad.webp', 'סלט קינואה ועדשים על מצע לאבנה בקערה כהה', 'שחזרתי בבית את סלט הספורטאיות של קפה גן סיפור, ומי אני שלא אעשה את זה.

מדובר בסלט עשיר עם קינואה, עדשים שחורות, המון ירקות ועשבי תיבול, על מצע של לאבנה ועם טחינה גולמית מעל. טעים ומזין ברמות.

הוא גם נשמר מעולה בקופסה במקרר 3 ימים, אז אני אוהבת להכין ממנו כמות ולאכול לאורך השבוע.', '[{"kind":"item","text":"כוס קינואה מבושלת"},{"kind":"item","text":"כוס עדשים שחורות מבושלות"},{"kind":"item","text":"2-3 מלפפונים"},{"kind":"item","text":"12-14 עגבניות שרי חצויות"},{"kind":"item","text":"בצל סגול קצוץ"},{"kind":"item","text":"צרור בצל ירוק קצוץ"},{"kind":"item","text":"חופן כוסברה, נענע ופטרוזיליה קצוצות"},{"kind":"item","text":"2-3 כפות אגוזי מלך שבורים"},{"kind":"item","text":"2-3 כפות חמוציות"},{"kind":"sublabel","text":"לרוטב:"},{"kind":"item","text":"3 כפות שמן זית"},{"kind":"item","text":"הרבה לימון"},{"kind":"item","text":"מלח"},{"kind":"item","text":"פלפל"},{"kind":"sublabel","text":"להגשה:"},{"kind":"item","text":"2 כפות לאבנה"},{"kind":"item","text":"כפית סומאק"},{"kind":"item","text":"2 כפות טחינה גולמית מעל"}]'::jsonb, '["מכינים את הקינואה והעדשים על פי הוראות ההכנה. מניחים בצד שיתקררו קצת ובינתיים חותכים את הירקות והרכיבים.","מערבבים את כל מרכיבי הסלט יחד בקערה גדולה, מתבלים בשמן זית, לימון, מלח ופלפל.","מורחים על צלחת הגשה לאבנה, מפזרים סומאק.","מניחים את הסלט על צלחת ההגשה עם הלאבנה בערימה.","מזלפים מעל טחינה גולמית. אפשר להוסיף עוד פיצוחים או שקדים, לא חובה."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-06-14T00:00:00Z'::timestamptz)
