values ('300f73f0-6876-5abc-8b6b-9e7cb370f097', 'quinoa-lentil-vegetable-bake', null, 'תבשיל קינואה, עדשים וירקות בתנור', 'קינואה, עדשים ירוקות והמון ירקות שנאפים יחד בתבנית אחת. ארוחה טבעונית מלאה בשיטת שגר ושכח, שנשמרת במקרר לכמה ימים.', '2025-12-21'::date, 'ערב', array['צמחוני', 'טבעוני', 'עתיר חלבון']::text[], 'לא צוין', null, null, '721b0e33-aeaa-5d9e-8d8b-8cf29ff417d7', '/media/client/recipes/quinoa-lentil-vegetable-bake.webp', 'תבנית קינואה ועדשים עם קוביות גזר, בצל סגול ופטרוזיליה טרייה', 'תבנית אחת, שיטת שגר ושכח, וארוחה מלאה יוצאת מהתנור: קינואה, עדשים ירוקות והמון ירקות.

אני אוהבת להכין את זה כשאני רוצה ארוחה מזינה בלי לעמוד ליד הכיריים. הכל נכנס לתבנית אחת, והתנור עושה את כל העבודה.', '[{"kind":"item","text":"כוס קינואה שטופה"},{"kind":"item","text":"3/4 כוס עדשים ירוקות שטופות"},{"kind":"item","text":"1 קישוא או זוקיני גדול חתוך לקוביות"},{"kind":"item","text":"1 גזר גדול או 2 קטנים חתוך לקוביות"},{"kind":"item","text":"1 בצל סגול חתוך לחתיכות גסות"},{"kind":"item","text":"מקל סלרי קצוץ"},{"kind":"item","text":"3-4 שיני שום כתושות"},{"kind":"item","text":"2 כפות שמן זית"},{"kind":"item","text":"2.5 כוסות מים רותחים"},{"kind":"item","text":"כף סויה"},{"kind":"item","text":"כף סילאן + זילוף סילאן נוסף לפני כניסה לתנור"},{"kind":"item","text":"כפית שטוחה מלח, מעט פלפל שחור, כפית פפריקה, אבקת שום"},{"kind":"item","text":"להגשה: פטרוזיליה"}]'::jsonb, '["מחממים תנור ל 200 מעלות.","שוטפים את הקינואה והעדשים.","מניחים בתבנית את הקינואה, העדשים והירקות, מוסיפים את הסלרי, השום והתבלינים ומערבבים.","מוסיפים מים רותחים, שמן, סויה וסילאן ומערבבים בתוך התבנית.","מכסים את התבנית בנייר אלומיניום ומכניסים לתנור ל 30 דקות, עד שהקינואה רכה. אם צריך מוסיפים עוד נוזלים תוך כדי האפייה.","אחרי 30 דקות מסירים את הכיסוי, מזלפים מעט סילאן ואופים 20-25 דקות נוספות.","מוציאים מהתנור, מערבבים ומפזרים פטרוזיליה להגשה.","מומלץ להעביר לקופסה ולשמור במקרר לכמה ימים."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2025-12-21T00:00:00Z'::timestamptz)
