values ('d8fbd2da-7893-5896-8304-2ff3b0142545', 'rice-paper-malawach', null, 'מלוואח קריספי מדפי אורז', 'מלוואח קריספי מדפי אורז, בלי בצק ובלי לישה, שנטבל בבלילת ביצה וסילאן ומטוגן במחבת. מתגלגל עם ביצה קשה, אבוקדו ורסק עגבניות.', '2026-08-09'::date, 'בוקר', array['קל ומהיר', 'צמחוני', 'ללא גלוטן']::text[], 'לא צוין', null, 'מלוואח אחד', '524ad4cf-d716-5861-81fc-cc3cc347170e', '/media/client/recipes/rice-paper-malawach.webp', 'שלושה מלוואח קריספיים על קרש עץ עם קערות ביצה ורסק', 'לפני שלוש שנים העליתי את המתכון הזה לאינסטגרם, והוא היה הראשון שממש התפוצץ לי בעמוד. הגיע הזמן לשחזר אותו בגרסה משודרגת.

מלוואח קריספי ברמות, בלי בצק ובלי לישה, רק שני דפי אורז שנטבלים בבלילת ביצה קלה ומטוגנים במחבת. אני ממלאת אותו במה שיש לי בבית, ביצה קשה, רסק עגבניות ואבוקדו, ומגלגלת.', '[{"kind":"sublabel","text":"למלוואח אחד:"},{"kind":"item","text":"2 דפי אורז"},{"kind":"item","text":"ביצה"},{"kind":"item","text":"רבע כוס מים"},{"kind":"item","text":"כפית סילאן"},{"kind":"item","text":"מלח"},{"kind":"sublabel","text":"תוספות:"},{"kind":"item","text":"ביצה קשה, רסק עגבניות, אבוקדו וכל מה שתרצו"}]'::jsonb, '["טורפים את הביצה עם המים, הסילאן והמלח.","טובלים את 2 דפי האורז בבלילת הביצה ל 2 שניות.","מחממים שמן זית במחבת, ומניחים את 2 דפי האורז אחד על גבי השני במחבת החמה.","מטגנים 2-3 דקות מכל צד, עד שהמלוואח נהיה קריספי ומשחים מכל כיוון. מורידים מהגז.","מוסיפים את התוספות, מגלגלים ובתיאבון."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-08-09T00:00:00Z'::timestamptz)
