values ('dcf87a18-e046-5360-8d28-caeed15ee8f8', 'rice-paper-omelette', null, 'חביתת דפי אורז קריספית', 'חביתה קריספית מדפי אורז עם ביצים וגבינה צהובה, מוכנה במחבת תוך דקות. משביעה, קלה להכנה וסוגרת את הפינה לארוחת בוקר או ערב.', '2026-05-31'::date, 'בוקר', array['קל ומהיר', 'צמחוני', 'ללא גלוטן', 'עתיר חלבון']::text[], 'לא צוין', null, null, 'd9e2f982-8cd9-5ecc-8d6d-9557200ebd2d', '/media/client/recipes/rice-paper-omelette.webp', 'חביתת דפי אורז מוזהבת וקריספית על קרש עץ', 'חביתה קריספית עם דפי אורז, הכי קלה שיש. היא משביעה לגמרי וסוגרת את הפינה גם לארוחת ערב וגם לארוחת בוקר.

אני אוהבת אותה במיוחד בימים שאין לי כוח לעמוד במטבח: כמה דקות במחבת, ויש צלחת חמה עם קצוות קריספיים.', '[{"kind":"item","text":"תרסיס שמן זית"},{"kind":"item","text":"4 דפי אורז"},{"kind":"item","text":"2 ביצים"},{"kind":"item","text":"2 פרוסות גבינה צהובה"},{"kind":"item","text":"תוספות לבחירתכם: בצל, זיתים, תירס, בולגרית"}]'::jsonb, '["מחממים מעט שמן זית במחבת.","טובלים 2 דפי אורז במים ומניחים במחבת החמה אחד על השני.","טורפים 2 ביצים, שופכים מעל דפי האורז שבמחבת ומוסיפים מעל את הגבינה הצהובה.","בשלב הזה אפשר להוסיף תוספות לבחירתכם.","מניחים מעל עוד 2 דפי אורז רטובים, מחכים דקה והופכים לצד השני.","צורבים 2-3 דקות גם מהצד השני. אפשר לקפל לחצי ולצרוב עד ששני הצדדים קריספיים. בתיאבון!"]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-05-31T00:00:00Z'::timestamptz)
