values ('a3629172-9571-5389-84fd-62b7c74d2ae1', 'rice-paper-pizza', null, 'פיצה מדפי אורז', 'פיצה ביתית על בסיס דפי אורז שנטבלים בבלילת ביצה ונאפים עד שהם קריספיים, עם רסק עגבניות, גבינה צהובה והתוספות שאתם אוהבים.', '2026-04-19'::date, 'ערב', array['קל ומהיר', 'צמחוני', 'ללא גלוטן']::text[], 'לא צוין', null, null, 'bcbf8083-fd89-5581-8203-af065bd214a8', '/media/client/recipes/rice-paper-pizza.webp', 'פיצת דפי אורז חתוכה לריבועים על נייר אפייה', 'פיצה דפי אורז או מאפה דפי אורז, תקראו לזה איך שבא לכם. ארוחת הערב הזאת הולכת לסגור לכם פינה.

קלה, מהירה, טעימה ויוצאת קריספית בקצוות. מה צריך יותר מזה?', '[{"kind":"item","text":"4 דפי אורז"},{"kind":"sublabel","text":"לבלילה:"},{"kind":"item","text":"ביצה"},{"kind":"item","text":"רבע כוס מים"},{"kind":"item","text":"כפית גדושה סילאן (נותן צבע, לא לוותר)"},{"kind":"item","text":"מלח"},{"kind":"sublabel","text":"לפיצה:"},{"kind":"item","text":"רסק עגבניות לבחירתכם"},{"kind":"item","text":"2 עד 3 פרוסות גבינה צהובה"},{"kind":"item","text":"תוספות לבחירתכם, אני שמתי בצל סגול, פלפל ירוק חריף וזיתי קלמטה"},{"kind":"sublabel","text":"להברשה לפני האפייה:"},{"kind":"item","text":"ביצה טרופה"},{"kind":"item","text":"שומשום לפיזור"}]'::jsonb, '["מדליקים תנור ל 200 מעלות.","משמנים קלות תבנית עם נייר אפייה.","טורפים בקערה או בצלחת עמוקה את הביצה עם המים, הסילאן והמלח.","טובלים כל דף אורז בבלילת הביצה.","מניחים 2 דפי אורז אחד ליד השני על נייר האפייה המשומן, כך שיעלו מעט אחד על השני, ומעליהם מניחים את 2 הדפים הנוספים.","מורחים את רסק העגבניות, מפזרים גבינה ואת התוספות שאתם אוהבים.","מקפלים את הקצוות של דפי האורז פנימה.","מברישים את הקצוות בביצה ומפזרים שומשום.","מכניסים לתנור ל 15 עד 20 דקות עד שהמאפה קריספי. בתיאבון."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-04-19T00:00:00Z'::timestamptz)
