values ('7b516fe1-4e18-5ee8-8f0f-fb9aead7c1b4', 'roasted-vegetable-antipasti', null, 'אנטיפסטי ירקות בתנור', 'מדריך לאנטיפסטי ירקות בתנור: חציל, בטטה, זוקיני, גזר, בצל סגול ופטריות עם שמן זית ורוזמרין. תוספת צבעונית שמסדרת ארוחות לכל השבוע.', '2025-07-27'::date, 'סלטים', array['צמחוני', 'ללא גלוטן']::text[], 'לא צוין', null, null, '46ff1c94-e606-50b2-843e-e08b08da2279', '/media/client/recipes/roasted-vegetable-antipasti.webp', 'מגש אנטיפסטי צבעוני עם חציל, בטטה, גזר ופלפלונים', 'קבלו מדריך לאנטיפסטי המושלם, ותסמכו עליי, זה מתחסל. זאת הדרך הכי טובה שאני מכירה לשלב יותר ירקות במהלך השבוע, והוא תוספת מעולה לצד הארוחות.

איכות חומרי הגלם היא הבסיס לאנטיפסטי טוב, ולכן חשוב להשתמש בירקות עונתיים שמתאימים לאפייה. אני משתדלת כמעט כל שבוע, כשמגיע משלוח הירקות, לפנות מהמקרר את הירקות שנותרו, לחתוך ולהכניס לתנור. הכי קל, ומסדר לי ארוחות במהלך השבוע.

גם ההגשה חשובה לא פחות: שלבו צבעים שונים וסידור מושך ומעורר תיאבון, ואין אחד שלא ירצה לקחת.', '[{"kind":"item","text":"1 חציל"},{"kind":"item","text":"2 בטטות בינוניות (שמתי אחת כתומה ואחת סגולה)"},{"kind":"item","text":"2 קישואים/זוקיני"},{"kind":"item","text":"3 גזרים"},{"kind":"item","text":"2 בצלים סגולים"},{"kind":"item","text":"חבילת פטריות"},{"kind":"item","text":"פלפלונים קטנים"},{"kind":"item","text":"ראש שום"},{"kind":"item","text":"גבעול רוזמרין (או עשבי תיבול כגון טימין, אורגנו)"},{"kind":"item","text":"3-4 כפות שמן זית"},{"kind":"item","text":"מלח גס ופלפל שחור גרוס/צ׳ילי גרוס"},{"kind":"item","text":"זילוף דבש / סילאן"}]'::jsonb, '["מכוונים את התנור ל-190 מעלות.","חותכים את החציל לפרוסות ולאחר מכן כל פרוסה לחצי.","חוצים את הבטטות לאורך ואז לצורת מקלות.","חוצים את הזוקיני והגזרים לאורך במרכז ולאחר מכן לרבעים. כדאי לחתוך את כל הירקות בגודל דומה, כדי שייאפו באופן אחיד.","חוצים את הבצל לחצי ואז לרבעים.","חוצים את ראש השום בחלק העליון כדי לחשוף את השיניים, מניחים על נייר אפייה, מזלפים עליו מעט שמן זית ועוטפים את ראש השום.","מניחים את הירקות על תבנית עם נייר אפייה, אפשר להוסיף עשבי תיבול (רוזמרין וכדומה), ומזלפים מעל הירקות שמן זית, מלח גס, פלפל גרוס וקצת סילאן (מוסיף ברמות).","אופים בתנור כ-40 דקות. יש תנורים עם אזורים חמים יותר, ולכן מומלץ להציץ על הירקות כל 15 דקות ובמידת הצורך לסובב את התבנית.","אם אופים 2 תבניות ירקות, ממליצה להחליף ביניהן פעם אחת במהלך האפייה, כדי שכל הירקות יקבלו חום שווה."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2025-07-27T00:00:00Z'::timestamptz)
