values ('9a9987dd-875f-52c1-8a2d-fe0809585802', 'soba-noodle-salad', 'soba-noodle-salad', 'סלט אטריות סובה', 'סלט אטריות סובה עם טופו מוקפץ, מלפפונים ועשבי תיבול ברוטב חמאת בוטנים, סויה וג׳ינג׳ר. מנת צהריים מזינה שמתכינים בקלות ובמהירות.', '2026-06-28'::date, 'סלטים', array['טבעוני', 'עתיר חלבון', 'קל ומהיר']::text[], 'לא צוין', null, null, '5927dbd0-0924-5c9d-8d50-fc753d9f201a', '/media/client/recipes/soba-noodle-salad.webp', 'קערה שחורה עם אטריות סובה, קוביות טופו וירקות ירוקים', 'סלט אטריות סובה הוא בדיוק מה שאני אוהבת לאכול בצהריים: מזין, מלא ירקות ועשבי תיבול, וקל להכנה.

הרוטב על בסיס חמאת בוטנים, סויה וג׳ינג׳ר טרי הוא מה שמחבר את הכל, והטופו המוקפץ הופך את הסלט למנה שבאמת משביעה.', '[{"kind":"item","text":"חצי חבילה אטריות סובה"},{"kind":"item","text":"חופן עלי קייל / תרד / חסה / רוקט"},{"kind":"item","text":"2 מלפפונים"},{"kind":"item","text":"צרור בצל ירוק"},{"kind":"item","text":"חופן כוסברה קצוצה"},{"kind":"item","text":"כף שומשום שחור"},{"kind":"item","text":"חבילת טופו"},{"kind":"sublabel","text":"לרוטב:"},{"kind":"item","text":"2-3 כפות חמאת בוטנים טבעית"},{"kind":"item","text":"4 כפות סויה"},{"kind":"item","text":"כף מייפל טבעי"},{"kind":"item","text":"כפית ג׳ינג׳ר טרי מגורד"},{"kind":"item","text":"מיץ לימון מחצי לימון טרי"},{"kind":"item","text":"צ׳ילי גרוס"},{"kind":"item","text":"1-2 כפות מים פושרים"}]'::jsonb, '["מכינים את אטריות הסובה לפי הוראות ההכנה במים רותחים 7 דקות, מסננים ושוטפים במים קרים.","חותכים את כל הירקות.","מניחים את האטריות בקערה גדולה, מוסיפים את שאר הרכיבים.","מקפיצים את הטופו בנפרד על מחבת כמה דקות עד שמשחים.","מערבבים בקערה נפרדת את הרוטב ושופכים על הסלט, מפזרים שומשום שחור.","מערבבים ושיהיה בתיאבון."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-06-28T00:00:00Z'::timestamptz)
