values ('24cfec2f-2111-5610-86be-d8bed234291b', 'spelt-carrot-cake', null, 'עוגת גזר עם קמח כוסמין', 'עוגת גזר רכה על בסיס קמח כוסמין, קמח שקדים ושמן זית, עם מיץ תפוזים סחוט וקינמון. המתכון האהוב על סבתא שלי.', '2025-10-26'::date, 'מתוקים', array['צמחוני']::text[], 'לא צוין', null, '2 אינגליש קייק', '37df0ea4-bba0-5ce0-8e47-e3c334cb500c', '/media/client/recipes/spelt-carrot-cake.webp', 'כיכר עוגת גזר מכוסה אבקת סוכר בתבנית, פרוסות ראשונות נחתכו', 'זו העוגה האהובה על סבתא שלי, שבכל פעם מבקשת ממני להכין ולהביא לה את עוגת הגזר שלי. היא בנויה על קמח כוסמין, קמח שקדים ושמן זית, עם מיץ תפוזים סחוט שנותן לה רכות.

וזה המעט שאנחנו יכולים לעשות עבור הסבים והסבתות המבוגרים שלנו, אז זו גם התזכורת שלנו להרים טלפון, לקפוץ לבקר, לשבת איתם ולהביא משהו טעים. זה עולם ומלואו, תהנו.', '[{"kind":"item","text":"4 ביצים"},{"kind":"item","text":"3/4 כוס סוכר חום"},{"kind":"item","text":"1/2 כוס שמן זית"},{"kind":"item","text":"1/2 כוס מיץ תפוזים סחוט או קלמנטינות"},{"kind":"item","text":"כפית תמצית וניל"},{"kind":"item","text":"כוס וחצי קמח כוסמין 80%"},{"kind":"item","text":"חצי כוס קמח שקדים"},{"kind":"item","text":"10 גרם אבקת אפייה"},{"kind":"item","text":"כפית קינמון"},{"kind":"item","text":"3 גזרים מגורדים"}]'::jsonb, '["מחממים תנור ל170 מעלות.","טורפים בקערה את הביצים עם הסוכר, מוסיפים את המיץ, השמן והוניל וטורפים לבלילה בהירה.","מוסיפים את היבשים: קמח כוסמין, קמח שקדים, אבקת אפייה וקינמון, ומערבבים היטב.","מוסיפים את הגזרים ומערבבים לאיחוד.","מעבירים ל2 תבניות אינגליש קייק משומנות.","מכניסים לתנור לאפייה של 40 דקות, עד שמכניסים קיסם והוא יוצא יבש.","אחרי שהעוגה מצטננת מעט, מומלץ לפזר מעליה אבקת סוכר."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2025-10-26T00:00:00Z'::timestamptz)
