values ('909e8611-5f44-5bdf-8647-4f8cbc5e90f7', 'sweet-and-sour-tofu', 'sweet-and-sour-tofu', 'טופו בקשיו ברוטב חמוץ מתוק', 'מוקפץ טופו וקשיו עם ירקות צבעוניים ורוטב חמוץ מתוק, בדיוק בסגנון המסעדה האסייתית האהובה, רק מזין יותר ומוכן במחבת אחת.', '2026-03-22'::date, 'ערב', array['צמחוני', 'טבעוני', 'עתיר חלבון', 'קל ומהיר']::text[], 'לא צוין', null, null, 'a27cf7fd-80bc-5dd2-8988-db5c78b14ca4', '/media/client/recipes/sweet-and-sour-tofu.webp', 'קערה שחורה עם אורז לבן וטופו בקשיו ברוטב', 'טופו בקשיו ברוטב חמוץ מתוק, בדיוק כמו שאני אוהבת להזמין במסעדה, רק שהפעם הכל קורה אצלי במחבת אחת והתוצאה יוצאת מזינה הרבה יותר.

הסוד נמצא בציפוי הקורנפלור, שנותן לקוביות הטופו קראסט זהוב ופריך, ובקשיו שמוסיף נגיסה מתוקה בין הירקות. אני מגישה על אורז לבן וזו ארוחה שלמה.', '[{"kind":"item","text":"300 גרם טופו רך של תנובה אלטרנטיב"},{"kind":"item","text":"כף קורנפלור"},{"kind":"item","text":"כף שמן זית"},{"kind":"item","text":"בצל סגול חתוך לריבועים גסים"},{"kind":"item","text":"4 שיני שום פרוסות"},{"kind":"item","text":"צ׳ילי אדום חריף פרוס"},{"kind":"item","text":"פלפל אדום חתוך גס"},{"kind":"item","text":"פרחי ברוקולי"},{"kind":"item","text":"באק צ׳וי, תרד או שעועית ירוקה, כל ירק שתבחרו"},{"kind":"item","text":"חופן קשיו"},{"kind":"item","text":"בצל ירוק חתוך לחתיכות גדולות"},{"kind":"sublabel","text":"לרוטב:"},{"kind":"item","text":"5 כפות רוטב סויה"},{"kind":"item","text":"כף סוכר חום"},{"kind":"item","text":"2 כפות חומץ אורז או מיץ לימון"},{"kind":"item","text":"כפית קורנפלור"},{"kind":"item","text":"3-4 כפות מים רותחים"}]'::jsonb, '["חותכים את הטופו לקוביות וסופגים בעזרת נייר סופג.","מצפים את קוביות הטופו בקורנפלור ומטגנים קלות במחבת רחבה (ווק) עם מעט שמן זית.","כשהטופו צרוב מוציאים אותו מהמחבת ומניחים בצד.","באותה מחבת מתחילים להקפיץ את הירקות: מוסיפים את הבצל הסגול, מקפיצים 2-3 דקות ומוסיפים את השום, הצ׳ילי האדום והקשיו, ומקפיצים יחד 2 דקות נוספות.","לאחר מכן מוסיפים את שאר הירקות (פלפל, ברוקולי, באק צ׳וי) ומקפיצים 5 דקות עד ריכוך קל.","מערבבים ומוסיפים את כל רכיבי הרוטב, שיעטוף את הירקות.","מחזירים את הטופו הצרוב למחבת ומקפיצים דקה נוספת כדי שהטופו יתעטף ברוטב. בסוף מוסיפים את הבצל הירוק.","מומלץ להגיש על אורז."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-03-22T00:00:00Z'::timestamptz)
