values ('f913ad6d-c169-50d5-8e28-3c44e4a5a580', 'sweet-potato-pumpkin-soup', null, 'מרק כתום עשיר ומפנק', 'מרק כתום סמיך ומנחם מבטטה, דלעת וגזר עם ג׳ינג׳ר טרי ועשבי תיבול. פשוט להכנה, מזין ומחמם בדיוק בימים הקרים של סוף החורף.', '2026-01-25'::date, 'מרקים', array['צמחוני', 'טבעוני', 'ללא גלוטן']::text[], 'לא צוין', null, null, '563f3ac4-988e-5a5c-815a-3d222a0d7347', '/media/client/recipes/sweet-potato-pumpkin-soup.webp', 'קערה שחורה עם מרק כתום וגרעינים לצד כפית זהב', 'רגע לפני שהחורף שוב נגמר לנו, זה הזמן לקום ולהכין מרק כתום מזין, טעים ומנחם.

אין מרק פשוט וטעים כמו הזה, בהבטחה. בטטה, דלעת וגזר שמתבשלים עם בצל, שום וג׳ינג׳ר טרי ונטחנים למרקם עשיר וסמיך שמחמם מבפנים.', '[{"kind":"item","text":"שמן זית"},{"kind":"item","text":"2 בטטות"},{"kind":"item","text":"3 גזרים"},{"kind":"item","text":"300-400 גרם דלעת חתוכה"},{"kind":"item","text":"1 בצל לבן"},{"kind":"item","text":"4 שיני שום"},{"kind":"item","text":"כפית ג׳ינג׳ר טרי"},{"kind":"item","text":"צרור פטרוזיליה"},{"kind":"item","text":"טימין"},{"kind":"item","text":"כפית מלח, כפית אבקת שום גבישי, פלפל שחור, חצי כפית כורכום"}]'::jsonb, '["מקלפים את הבטטות, הדלעת והגזר וחותכים את כל הירקות לקוביות בינוניות. את הבצל חותכים לרבע.","מחממים שמן זית בסיר, מטגנים קלות את הבצל והשום עד השחמה קלה. מוסיפים את הבטטה, הדלעת, הגזר, הג׳ינג׳ר ועשבי התיבול ומערבבים.","מתבלים ומוסיפים לסיר מים רותחים עד כיסוי כל הירקות.","מערבבים, מכסים ומבשלים על אש בינונית בערך 30 דקות עד ריכוך הירקות.","טוחנים למרקם עשיר וסמיך (אפשר להוסיף מים במידת הצורך וגם לתקן תיבול).","נותנים בישול נוסף של 5 דקות אחרי הטחינה וטועמים אם צריך עוד תיבול."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-01-25T00:00:00Z'::timestamptz)
