values ('b25d6a45-446a-5e13-81bd-f1daa96e230b', 'thai-pomelo-salad', null, 'סלט פומלה תאילנדי', 'סלט פומלה תאילנדי מרענן עם למון גראס, נענע, כוסברה ובוטנים קלויים ברוטב חמצמץ וחריף. ממכר, לא מסובך ומוכן בלי שום בישול.', '2026-02-08'::date, 'סלטים', array['קל ומהיר', 'ללא גלוטן']::text[], 'לא צוין', null, null, 'ff7649f0-eb5e-5faf-8ec4-ac38ef4a95f0', '/media/client/recipes/thai-pomelo-salad.webp', 'קערה לבנה עם סלט פומלה תאילנדי על שולחן עץ', 'סלט הפומלה התאילנדי הזה הוא בין המתכונים האהובים עלי במטבח התאילנדי, וההבטחה שלי היא שהוא ממש לא מסובך.

עד שאגיע שוב לתאילנד, אני מנצלת את עונת הפומלות ומכינה אותו בבית. אני השתמשתי בפומלה קלופה מוכנה, כי אין לי סבלנות לקלף אותה לבד, אבל אם אתם מרחיקי לכת זו לגמרי אופציה.', '[{"kind":"item","text":"חבילת פומלה קלופה"},{"kind":"item","text":"מלפפון חתוך לחצאי ירח"},{"kind":"item","text":"בצל שאלוט או בצל סגול פרוס דק"},{"kind":"item","text":"צ׳ילי אדום חריף פרוס"},{"kind":"item","text":"בצל ירוק"},{"kind":"item","text":"חופן עלי נענע"},{"kind":"item","text":"חופן עלי כוסברה"},{"kind":"item","text":"1 מקל למון גראס חתוך דק (מהחלק של השורש הבהיר יותר)"},{"kind":"item","text":"3 כפות בוטנים קלויים"},{"kind":"sublabel","text":"לרוטב:"},{"kind":"item","text":"מיץ מליים או לימון שלם"},{"kind":"item","text":"3 כפות רוטב דגים"},{"kind":"item","text":"כף סוכר חום"},{"kind":"item","text":"כף מים רותחים"},{"kind":"item","text":"3 שיני שום כתושות"},{"kind":"item","text":"1/4 צ׳ילי אדום קצוץ או 1/2 כפית צ׳ילי גרוס"}]'::jsonb, '["פורסים את הבצלים, הצ׳ילי, המלפפון והלמון גראס. חותכים גס את הנענע והכוסברה.","מעבירים הכל לקערה גדולה. מוסיפים את חתיכות הפומלה ואת הבוטנים.","לרוטב: בקערה מערבבים את הסוכר החום עם כף מים רותחים עד שנמס. מוסיפים את הלימון, רוטב הדגים, השום והצ׳ילי ומערבבים לאיחוד.","שופכים את הרוטב מעל הסלט ומערבבים."]'::jsonb, '', 'זהו, זה הכי טעים ושווה שיש, בהבטחה.', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-02-08T00:00:00Z'::timestamptz)
