values ('2f8fd271-2524-5e70-86ec-aab3acab617e', 'three-ingredient-date-balls', 'three-ingredient-date-balls', 'כדורי תמרים בטעם טראפלס שוקולד', 'כדורי תמרים במרקם של טראפלס שוקולד מריר, מתמרי מג׳הול, קמח שקדים ואבקת קקאו. חמש דקות עבודה ומתוק מושלם ליד הקפה.', '2026-02-01'::date, 'מתוקים', array['קל ומהיר', 'צמחוני', 'ללא גלוטן']::text[], '5 דקות', 5, null, '7d3c52e2-3bce-5ae7-8163-803385b10743', '/media/client/recipes/three-ingredient-date-balls.webp', 'קערית לבנה עם כדורי תמרים בציפוי קקאו וקוקוס', 'כדורי תמרים שמרגישים כמו טראפלס שוקולד מריר, ארבעה מרכיבים וחמש דקות הכנה.

זה בדיוק המתוק שאני צריכה ליד הקפה שלי: גם טעים ומספק, גם מזין וגם מהיר. הייתי ממשיכה לכתוב כמה הם עשירים ברמות, אבל אתם פשוט תצטרכו לנסות אותם כדי להבין.', '[{"kind":"item","text":"6-7 תמרי מג׳הול עסיסיים"},{"kind":"item","text":"2 כפות קמח שקדים"},{"kind":"item","text":"2 כפות אבקת קקאו"},{"kind":"item","text":"2 כפות פולי קקאו גרוסים או שוקולד צ׳יפס"},{"kind":"item","text":"כפית תמצית וניל"},{"kind":"sublabel","text":"לציפוי:"},{"kind":"item","text":"קוקוס טחון, אבקת שוקומאקה או קקאו איכותי"}]'::jsonb, '["משרים את התמרים במים חמים 10 דקות.","מסננים ומעבירים למעבד מזון עם שאר הרכיבים וטוחנים עד מרקם אחיד.","יוצרים כדורים ומגלגלים בציפוי.","מכניסים למקפיא לשעה לפחות.","נהנים מכל ביס."]'::jsonb, '', 'מומלץ לשמור אותם במקפיא או במקרר, אני באופן אישי מעדיפה במקפיא.', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-02-01T00:00:00Z'::timestamptz)
