values ('f3a83a5c-8d8b-562a-81d5-363b64857009', 'tofu-satay-skewers', null, 'שיפודי טופו ברוטב סאטה בוטנים', 'שיפודי טופו צרובים במחבת עם רוטב סאטה קרמי של חמאת בוטנים, סילאן וג''ינג''ר טרי. מנה טבעונית עשירה בחלבון שמוכנה מהר ומרגישה כמו אוכל רחוב.', '2025-12-07'::date, 'ערב', array['צמחוני', 'טבעוני', 'עתיר חלבון']::text[], 'לא צוין', null, null, '8df2834f-0383-5b22-8986-2d3d25114ab9', '/media/client/recipes/tofu-satay-skewers.webp', 'שיפודי טופו בצלחת עם רוטב בוטנים, בצל ירוק וצ''ילי', 'שיפודי הטופו האלה הם המתכון שגורם להתאהב בטופו, גם למי שעדיין לא בטוח לגביו. הטופו נצרב במחבת עד שהוא מזהיב בחוץ, ומעליו רוטב סאטה קרמי בטירוף של חמאת בוטנים, סילאן ונוזל קוקוס.

אני אוהבת להגיש את השיפודים עם בצל ירוק קצוץ, בוטנים וצ''ילי אדום מעל. בתיאבון!', '[{"kind":"item","text":"300 גרם (חבילה) טופו"},{"kind":"item","text":"כף שמן קוקוס"},{"kind":"item","text":"בצל ירוק (עדיפות לחלקים הבהירים יותר)"},{"kind":"sublabel","text":"לרוטב סאטה חמאת בוטנים:"},{"kind":"item","text":"1/4 כוס חמאת בוטנים טבעית"},{"kind":"item","text":"3 כפות סילאן"},{"kind":"item","text":"1/4 כוס נוזל קוקוס"},{"kind":"item","text":"2 כפות רוטב סויה"},{"kind":"item","text":"1 שן שום כתושה"},{"kind":"item","text":"מיץ לימון מחצי לימון טרי"},{"kind":"item","text":"כפית ג''ינג''ר טרי מגורד"},{"kind":"sublabel","text":"להגשה (אופציונלי):"},{"kind":"item","text":"בצל ירוק קצוץ"},{"kind":"item","text":"בוטנים קצוצים"},{"kind":"item","text":"צ''ילי אדום חתוך"}]'::jsonb, '["חותכים את הטופו לקוביות גדולות יחסית ומייבשים היטב בעזרת נייר סופג.","חותכים את הבצל הירוק בחלקים הגסים והבהירים יותר.","משפדים את קוביות הטופו והבצל הירוק על שיפודים, 3 קוביות טופו לכל שיפוד.","מחממים את השמן במחבת רחבה, וכשהשמן חם צורבים את שיפודי הטופו מכל צד עד השחמה.","בקערה או בסיר קטן מערבבים היטב את כל רכיבי הרוטב ומחממים מעט במיקרו או על הגז (לא לרתיחה, לחימום קל).","שופכים את הרוטב מעל שיפודי הטופו, מפזרים בצל ירוק, בוטנים וצ''ילי ומגישים."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2025-12-07T00:00:00Z'::timestamptz)
