values ('7076176f-6818-5eba-852c-9053e676318d', 'tofu-shawarma', 'tofu-shawarma', 'סלט שווארמה טופו', 'שווארמה טופו עם כרוב ובצל מוזהב, בצל בסומק וטחינה מעל. מנה צמחונית עשירה בחלבון שגם מצוינת כהכנה מראש לשבוע.', '2025-09-28'::date, 'צהריים', array['צמחוני', 'טבעוני', 'עתיר חלבון']::text[], 'לא צוין', null, null, 'd0d1bf5d-af94-5abd-8327-dd782694df3e', '/media/client/recipes/tofu-shawarma.webp', 'צלחת סלט שווארמה טופו עם כרוב סגול וטחינה, מאחור מחבת', 'תגידו מה שתרצו על טופו, אבל אין ספק שזה חלבון סופר קליל להכנה שלגמרי סוגר פינה. יצא לי כאן סלט עם מלא נפח, קל להכנה, ומצוין גם כהכנה מראש להמשך השבוע.

הבצל בסומק המהיר הוא מה שמרים לי את כל הצלחת, אז שווה לא לוותר עליו, וכמובן קצת טחינה מעל.', '[{"kind":"sublabel","text":"לשווארמה טופו:"},{"kind":"item","text":"2 כפות שמן זית"},{"kind":"item","text":"1 בצל לבן פרוס לפרוסות"},{"kind":"item","text":"1/2 כרוב לבן"},{"kind":"item","text":"3 שיני שום כתושות"},{"kind":"item","text":"300 גרם (חבילה) טופו"},{"kind":"item","text":"2 כפות תבלין שווארמה, או: כפית שטוחה מלח, כפית שטוחה שום גבישי, 1/3 כפית כורכום, 1/3 כפית כמון, 1/2 כפית פפריקה מתוקה, מעט פלפל שחור, 1/3 כפית קינמון"},{"kind":"sublabel","text":"לבצל בסומק מהיר:"},{"kind":"item","text":"1 בצל סגול פרוס"},{"kind":"item","text":"פטרוזיליה קצוצה"},{"kind":"item","text":"כף שמן זית"},{"kind":"item","text":"מיץ לימון מחצי לימון טרי"},{"kind":"item","text":"כפית גדושה סומק"},{"kind":"item","text":"כפית מלח"}]'::jsonb, '["פורסים את הבצל והכרוב לרצועות.","מחממים שמן זית במחבת רחבה, מוסיפים את הבצל, השום והכרוב ומקפיצים תוך כדי ערבוב כמה דקות עד שהבצל משחים והכרוב מצטמצם. מומלץ לשים מעט מלח כדי לעזור להם להוציא נוזלים.","מגרדים את הטופו במגרדת או מפוררים אותו עם הידיים ומעבירים למחבת עם הכרוב והבצל. מוסיפים את התבלינים ומערבבים היטב כמה דקות עד שכל הטופו מזהיב ומקבל צבע יפה.","בינתיים מכינים את הבצל: בקערה מניחים את רצועות הבצל הסגול, פטרוזיליה, לימון, שמן, סומק ומלח, מערבבים היטב ומכניסים למקרר ל30 דקות לפחות.","מרכיבים את הסלט עם הירקות שתרצו, מוסיפים את השווארמה ואת הבצל, ומומלץ גם טחינה."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2025-09-28T00:00:00Z'::timestamptz)
