values ('21ad27cf-e52d-5c89-8e7c-9534130d0148', 'tuna-arayes', null, 'עראייס טונה', 'עראייס טונה בפיתה: מילוי טונה עם ביצה, בצל סגול ועגבנייה מגוררת שנאפה עד השחמה פריכה. מנה פשוטה ומשביעה לארוחה באמצע השבוע.', '2026-06-07'::date, 'ערב', array['עתיר חלבון', 'קל ומהיר']::text[], 'לא צוין', null, null, 'c8a48ea4-4cda-52a6-89ae-e0b71a454207', '/media/client/recipes/tuna-arayes.webp', 'עראייס טונה על קרש עץ עם טחינה וזיתים', 'עראייס טונה הכי פשוט שיש, ומנה שנכנסה אצלי לארוחות הקבועות של אמצע השבוע.

מערבבים טונה עם ביצה, בצל סגול, עשבי תיבול ועגבנייה מגוררת שנותנת לחות חשובה, ממלאים את הפיתות ואופים עד השחמה. אם עדיין לא ניסיתם, זה הזמן.', '[{"kind":"item","text":"4-5 פיתות כוסמין / רגילות (חתוכות לחצאים או רבעים)"},{"kind":"item","text":"2 קופסאות טונה (במים / שמן)"},{"kind":"item","text":"ביצה"},{"kind":"item","text":"בצל סגול קצוץ"},{"kind":"item","text":"פטרוזיליה וכוסברה קצוצות"},{"kind":"item","text":"כפית פפריקה, 1/2 כפית מלח, פלפל שחור, כפית שטוחה אבקת שום גבישי"},{"kind":"item","text":"1 עגבנייה מגוררת בפומפייה (מוסיפה לחות חשובה)"},{"kind":"item","text":"שמן זית להברשת הפיתות"}]'::jsonb, '["בקערה מערבבים היטב את הטונה, הבצל הקצוץ, עשבי התיבול, הביצה, העגבנייה המגוררת והתבלינים לתערובת אחידה.","פותחים בעדינות כל חצי פיתה וממלאים בכמות נדיבה מתערובת הטונה. מהדקים מעט את הפיתה מבחוץ שהמילוי יתפזר בצורה שווה וישב טוב בפנים.","משמנים את הפיתות עם שמן זית מ 2 הצדדים ובאזור של הפתח עם הטונה.","להכנה יש 2 אופציות, אני הכנתי בנינג׳ה גריל.","אופציה א׳, בנינג׳ה או תנור: מחממים תנור או נינג׳ה ל-200°C (נינג׳ה במצב אייר פריי), מניחים את הפיתות, ואופים כ-12-15 דקות עד להשחמה יפה מכל הצדדים.","אופציה ב׳, על מחבת: מחממים מחבת, מניחים את הפיתות כשהפתח עם הטונה פונה כלפי מטה (למשך 2 דקות) כדי לסגור את המילוי. לאחר מכן הופכים וצולים עוד 3-4 דקות מכל צד.","מומלץ להגיש לצד טחינה וסלט ירקות."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-06-07T00:00:00Z'::timestamptz)
