values ('da487248-16d4-5a25-823d-ce6e1be48455', 'tuna-bolognese', null, 'בולונז טונה לפסטה', 'רוטב בולונז טונה עשיר בחלבון עם בצל, גזר, סלרי ורסק עגבניות, מתבשל בסיר אחד ומוגש על פסטה, אורז או בורגול.', '2026-08-02'::date, 'ערב', array['עתיר חלבון', 'קל ומהיר']::text[], 'לא צוין', null, null, '1d308d86-0f62-55ad-8275-da5f2a6196c2', '/media/client/recipes/tuna-bolognese.webp', 'צלחת פסטה פוסילי ברוטב טונה עם פרמזן ובזיליקום', 'בולונז טונה או פסטה טונה, איך שבא לכם לקרוא לזה. מנה כל כך קלה להכנה, עשירה בחלבון וסוגרת פינה, שפשוט חבל לא לנסות אותה.

אני אוהבת להגיש אותה על אורז, בורגול או פסטה, מה שבא לכם, ולגרד מעל קצת פרמזן.', '[{"kind":"item","text":"2 כפות שמן זית"},{"kind":"item","text":"1 בצל לבן קצוץ"},{"kind":"item","text":"3 שיני שום כתושות"},{"kind":"item","text":"סלרי קצוץ דק"},{"kind":"item","text":"2-3 גזרים חתוכים לקוביות קטנות"},{"kind":"item","text":"3 קופסאות טונה במים או בשמן, מסוננות"},{"kind":"item","text":"קופסת רסק עגבניות חתוכות דק (400 גרם)"},{"kind":"item","text":"2 כפות רסק עגבניות מרוכז"},{"kind":"item","text":"כף סילאן"},{"kind":"item","text":"כפית מלח, כפית פפריקה, פלפל שחור, צ׳ילי גרוס"},{"kind":"item","text":"כוס מי בישול מהפסטה או מים רותחים"},{"kind":"item","text":"פסטה לבחירתכם לפי הוראות היצרן"}]'::jsonb, '["קוצצים את כל הירקות, בצל, גזר, סלרי ושום.","מחממים שמן זית במחבת רחבה (סוטאז) ומטגנים את הבצל עד שהוא מתרכך קלות ונהיה מעט שקוף, מוסיפים את הגזר, השום והסלרי ומטגנים כמה דקות.","מוסיפים את הטונה, התבלינים ומערבבים.","שופכים את העגבניות והסילאן, מערבבים, מוסיפים את המים, מביאים לרתיחה, מכסים ומבשלים 15-20 דקות על אש נמוכה עד בינונית.","לאחר מכן פותחים את המכסה, מערבבים, טועמים ומוסיפים אם משהו חסר.","מומלץ להגיש על פסטה, אורז או בורגול, ואפשר לגרד מעל פרמזן. בתיאבון."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-08-02T00:00:00Z'::timestamptz)
