values ('bfe747b4-137b-5069-8054-202d9db90e1c', 'tuna-melt-sandwich', null, 'כריך טונה מלט בגרסת הדיאטנית', 'כריך טונה חם וקריספי עם בצל סגול, חרדל דיז''ון וגבינה צהובה מותכת. עתיר חלבון, מוכן במחבת אחת ומוגש לצד ירקות.', '2026-01-04'::date, 'צהריים', array['קל ומהיר', 'עתיר חלבון']::text[], 'לא צוין', null, null, 'f7d58712-fb25-5f4f-83fb-98e72b92198b', '/media/client/recipes/tuna-melt-sandwich.webp', 'יד מחזיקה כריך טונה חתוך לצד מקלות מלפפון ועגבניות שרי', 'טונה מלט בגרסת הדיאטנית: מלא בחלבון, קריספי ברמות וסוגר את הפינה.

זה הכריך שאני מכינה כשאין לי כוח לבשל ואני עדיין רוצה ארוחה אמיתית. הכל קורה במחבת אחת, תוך כמה דקות.', '[{"kind":"item","text":"2 פרוסות לחם מלא / מחמצת / כוסמין / לבחירתכם"},{"kind":"sublabel","text":"לממרח הטונה:"},{"kind":"item","text":"קופסת טונה במים"},{"kind":"item","text":"בצל סגול קצוץ"},{"kind":"item","text":"עירית או בצל ירוק קצוץ"},{"kind":"item","text":"כף מיונז לייט"},{"kind":"item","text":"כפית חרדל דיז''ון"},{"kind":"item","text":"לימון"},{"kind":"item","text":"מלח, צ''ילי גרוס"},{"kind":"sublabel","text":"להרכבת הכריך:"},{"kind":"item","text":"2 פרוסות גבינה צהובה 9-15%"},{"kind":"item","text":"שמן זית"}]'::jsonb, '["מערבבים את הרכיבים לממרח הטונה.","מורחים מעט שמן זית על 2 פרוסות הלחם מצד אחד.","בצד השני של הפרוסות: על פרוסה אחת מניחים את ממרח הטונה, על הפרוסה השנייה מניחים את הגבינה הצהובה, וסוגרים לכריך.","מחממים מחבת וצורבים את הכריך 2-3 דקות מכל צד, עד שהוא נהיה קריספי ומשחים.","חוצים ומגישים לצד ירקות."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2026-01-04T00:00:00Z'::timestamptz)
