values ('34882d03-0a95-5e50-85d7-6032fa782d0b', 'upside-down-pear-cake', null, 'עוגת אגסים הפוכה עם שמנת חמוצה', 'עוגת אגסים הפוכה, עסיסית ורכה, עם שמנת חמוצה וקמח שקדים ושכבת אגסים מבושלים בקינמון. מושלמת לקינוח לצד כדור גלידת וניל.', '2025-11-30'::date, 'מתוקים', array['צמחוני']::text[], 'לא צוין', null, null, '05244a01-0e2d-5767-853b-3dda01e8989e', '/media/client/recipes/upside-down-pear-cake.webp', 'פרוסה מעוגת האגסים ההפוכה לצד כדור גלידת וניל', 'עוגת אגסים הפוכה, עסיסית ורכה, עם שמנת חמוצה בבלילה וקצת קמח שקדים. שכבת האגסים מתבשלת עם מקל קינמון, נשכבת בתחתית התבנית, ובסוף מתהפכת והופכת לצד היפה של העוגה.

הצעת ההגשה שלי: פרוסה לצד גלידת וניל. בתיאבון!', '[{"kind":"sublabel","text":"לעוגה:"},{"kind":"item","text":"3 ביצים L"},{"kind":"item","text":"1/2 כוס סוכר"},{"kind":"item","text":"1/2 כוס שמן זית"},{"kind":"item","text":"200 גרם (גביע) שמנת חמוצה 9-15%"},{"kind":"item","text":"כפית תמצית וניל"},{"kind":"item","text":"כוס קמח כוסמין"},{"kind":"item","text":"1/2 כוס קמח שקדים"},{"kind":"item","text":"10 גרם (שקית) אבקת אפיה"},{"kind":"item","text":"2 אגסים אמריקאים חתוכים לקוביות"},{"kind":"sublabel","text":"לשכבת האגסים:"},{"kind":"item","text":"4-5 אגסים ירוקים ואדומים פרוסים לרצועות דקות"},{"kind":"item","text":"כף סוכר + מקל קינמון + 2 כוסות מים רותחים"},{"kind":"item","text":"כף סוכר + כפית קינמון"}]'::jsonb, '["מחממים תנור ל 180 מעלות.","חותכים את האגסים לרצועות דקות ומעבירים לסיר, מוסיפים כף סוכר, מקל קינמון ו 2 כוסות מים ומעבירים לבישול על אש בינונית ל 15-20 דקות.","בזמן הזה מוסיפים לקערה גדולה את הביצים והסוכר וטורפים. מוסיפים את השמן, שמנת חמוצה, וניל ומערבבים לאיחוד.","מוסיפים את הקמחים, אבקת האפיה והקינמון ומערבבים.","מוסיפים את קוביות האגסים ומערבבים רק עד לאיחוד.","מניחים את רצועות האגסים בתחתית התבנית על גבי נייר אפיה משומן מעט בצורה מעגלית, עד שכל תחתית התבנית מכוסה באגסים. מפזרים סוכר וקינמון ושופכים את תערובת העוגה מעל.","אופים כ 30 עד 35 דקות, עד שמכניסים קיסם והוא יוצא יבש עם מעט פירורים.","אחרי שהעוגה מצטננת, הופכים את העוגה בזהירות, מורידים את נייר האפייה ופורסים."]'::jsonb, '', '', '{"ingredients":"רכיבים","steps":"אופן הכנה","tip":"טיפ"}'::jsonb, 'published'::public.content_status, '2025-11-30T00:00:00Z'::timestamptz)
on conflict (id) do update set
  legacy_slug = excluded.legacy_slug,
  title = excluded.title,
  description = excluded.description,
  date = excluded.date,
  category = excluded.category,
  tags = excluded.tags,
  prep_time_text = excluded.prep_time_text,
  prep_minutes = excluded.prep_minutes,
  servings = excluded.servings,
  image_id = excluded.image_id,
  image_path = excluded.image_path,
  image_alt = excluded.image_alt,
  intro = excluded.intro,
  ingredients = excluded.ingredients,
  steps = excluded.steps,
  tip = excluded.tip,
  extra = excluded.extra,
  headings = excluded.headings;

-- ── the published edges of the media reference graph ───────────────────────
-- publish_entity maintains these from here on; the migration seeds them so the
-- delete guard in the media library is not empty on day one, which fails in the
-- unsafe direction (an asset with no edges looks free to delete).
insert into public.media_refs (media_id, ref_kind, entity_type, entity_id, field)
select r.image_id, 'published', 'recipe', r.id, 'image_id'
  from public.recipes r
 where r.image_id is not null
on conflict do nothing;

commit;
